import{j as r}from"./vendor-react-DzFdt34V.js";import{f as a,E as k,M as p}from"./LabKit-CJmjTJ9q.js";import{n as $}from"./notation-BaZ3uylG.js";const e=(t,n,u,l)=>({eu:t,es:n,en:l,ar:u.replace(/\{,\}/g,".")}),i=t=>e(t,t,t,t),g={meaning:{vocabulary:[e("zati berdinak","partes iguales","أجزاء متساوية","equal parts"),e("zatiketa","división","القسمة","division")],definitions:[{term:e("Izendatzailea","Denominador","المقام","Denominator"),meaning:e("Beheko zenbakia: unitatea zenbat zati berdinetan banatzen den.","El número de abajo: en cuántas partes iguales se divide la unidad.","العدد في الأسفل: عدد الأجزاء المتساوية التي تُقسم إليها الوحدة.","The bottom number: how many equal parts the whole is divided into.")},{term:e("Zenbakitzailea","Numerador","البسط","Numerator"),meaning:e("Goiko zenbakia: zati horietatik zenbat hartzen diren.","El número de arriba: cuántas de esas partes se toman.","العدد في الأعلى: عدد الأجزاء المأخوذة منها.","The top number: how many of those parts are taken.")}],explanation:e("Zatiki bera hiru modutara irakur daiteke: osoaren zati gisa, zatiketa baten emaitza gisa eta zenbaki-zuzeneko puntu bat gisa.","La misma fracción se puede leer de tres maneras: como parte de un todo, como el resultado de una división y como un punto de la recta numérica.","يمكن قراءة الكسر نفسه بثلاث طرق: جزءًا من كل، وناتجَ قسمة، ونقطةً على خط الأعداد.","The same fraction can be read in three ways: as part of a whole, as the result of a division and as a point on the number line."),examplePrompt:e("5 pizza berdin 8 lagunen artean banatzen dira. Pizzaren zer zati jaten du bakoitzak? Zer zenbaki da?","Se reparten 5 pizzas iguales entre 8 amigos. ¿Qué parte de pizza come cada uno? ¿Qué número es?","تُوزَّع 5 بيتزا متماثلة على 8 أصدقاء. ما الجزء الذي يأكله كل واحد؟ وأي عدد هو؟","5 identical pizzas are shared among 8 friends. What part of a pizza does each one eat? What number is it?"),example:i("$\\frac{5}{8}=5\\div 8=0{,}625$"),exampleAnswer:e("Bakoitzak pizzaren $\\frac{5}{8}$ jaten du: 0 eta 1 arteko zenbaki bat.","Cada uno come $\\frac{5}{8}$ de pizza: un número entre 0 y 1.","يأكل كل واحد $\\frac{5}{8}$ من البيتزا: عدد بين 0 و1.","Each one eats $\\frac{5}{8}$ of a pizza: a number between 0 and 1.")},representation:{vocabulary:[e("zenbaki osoa","número entero","العدد الصحيح","whole number"),e("hondarra","resto","الباقي","remainder")],definitions:[{term:e("Zatiki propioa","Fracción propia","الكسر الحقيقي","Proper fraction"),meaning:e("Zenbakitzailea izendatzailea baino txikiagoa da: 1 baino gutxiago balio du.","El numerador es menor que el denominador: vale menos que 1.","بسطه أصغر من مقامه: قيمته أقل من 1.","The numerator is smaller than the denominator: it is worth less than 1.")},{term:e("Zatiki inpropioa","Fracción impropia","الكسر غير الحقيقي","Improper fraction"),meaning:e("Zenbakitzailea izendatzailea baino handiagoa da: 1 baino gehiago balio du, eta zenbaki misto gisa idatz daiteke.","El numerador es mayor que el denominador: vale más que 1 y se puede escribir como número mixto.","بسطه أكبر من مقامه: قيمته أكثر من 1، ويمكن كتابته عددًا كسريًا.","The numerator is bigger than the denominator: it is worth more than 1 and can be written as a mixed number.")},{term:e("Zenbaki mistoa","Número mixto","العدد الكسري","Mixed number"),meaning:e("Zenbaki oso bat gehi zatiki propio bat, $2\\frac{1}{4}$ bezala.","Un entero más una fracción propia, como $2\\frac{1}{4}$.","عدد صحيح مع كسر حقيقي، مثل $2\\frac{1}{4}$.","A whole number plus a proper fraction, like $2\\frac{1}{4}$.")}],explanation:e("Zenbakitzailearen eta izendatzailearen arteko zatiketa osoak unitate osoak (zatidura) eta soberan geratzen dena (hondarra) ematen ditu; hondarra geratzen den zatiaren zenbakitzailea da. Izendatzailea ez da aldatzen.","La división entera del numerador entre el denominador da las unidades completas (el cociente) y lo que sobra (el resto), que es el numerador de la parte que queda. El denominador no cambia.","تعطي القسمة الصحيحة للبسط على المقام الوحدات الكاملة (الناتج) وما يتبقى (الباقي)، وهو بسط الجزء المتبقي. والمقام لا يتغير.","The whole-number division of the numerator by the denominator gives the whole units (the quotient) and what is left (the remainder), which is the numerator of the part left over. The denominator does not change."),examplePrompt:e("Idatzi $\\frac{31}{7}$ zenbaki misto gisa eta hamartar hurbildu gisa.","Escribe $\\frac{31}{7}$ como número mixto y como decimal aproximado.","اكتب $\\frac{31}{7}$ عددًا كسريًا وعددًا عشريًا تقريبيًا.","Write $\\frac{31}{7}$ as a mixed number and as an approximate decimal."),example:i("$\\begin{gathered}31=7\\cdot 4+3\\\\\\frac{31}{7}=4\\frac{3}{7}\\approx 4{,}43\\end{gathered}$"),exampleAnswer:e("$4\\frac{3}{7}$: 4 unitate oso, eta $\\frac{3}{7}$ soberan.","$4\\frac{3}{7}$: 4 unidades completas y sobran $\\frac{3}{7}$.","$4\\frac{3}{7}$: أربع وحدات كاملة ويتبقى $\\frac{3}{7}$.","$4\\frac{3}{7}$: 4 whole units and $\\frac{3}{7}$ left over.")},equivalence:{vocabulary:[e("biderkatu","multiplicar","اضرب","multiply"),e("zatitu","dividir","اقسم","divide"),e("biderkadura gurutzatuak","productos cruzados","الضرب التبادلي","cross products")],definitions:[{term:e("Zatiki baliokideak","Fracciones equivalentes","الكسور المتكافئة","Equivalent fractions"),meaning:e("Kantitate bera adierazten duten zatikiak, zenbaki desberdinekin idatzita egon arren.","Las que representan la misma cantidad, aunque se escriban con números distintos.","كسور تمثّل الكمية نفسها وإن كُتبت بأعداد مختلفة.","Fractions that stand for the same amount, even though they are written with different numbers.")}],why:{text:e("Zati bakoitza 2 zatitan banatzen baduzu, zati kopurua bikoiztu egiten da, baina bakoitza erdia da: kantitatea ez da aldatzen. Horregatik, zenbakitzailea eta izendatzailea zenbaki berarekin biderkatuta zatiki baliokide bat lortzen da.","Si partes cada trozo en 2, tienes el doble de trozos, pero cada uno es la mitad de grande: la cantidad no cambia. Por eso, multiplicar el numerador y el denominador por el mismo número da una fracción equivalente.","إذا قسمت كل قطعة إلى قسمين صار عدد القطع ضعفين، لكن كل قطعة صارت نصف ما كانت: الكمية لا تتغير. لذلك فإن ضرب البسط والمقام في العدد نفسه يعطي كسرًا مكافئًا.","If you cut each piece in 2, you get twice as many pieces, but each one is half the size: the amount does not change. That is why multiplying the numerator and the denominator by the same number gives an equivalent fraction."),math:i("$\\frac{2}{3}=\\frac{2\\cdot 2}{3\\cdot 2}=\\frac{4}{6}$")},explanation:e("Zenbakitzailea eta izendatzailea zero ez den zenbaki berarekin biderkatuz (anplifikatu) edo zatituz (sinplifikatu) lortzen dira. Bi zatiki baliokideak diren jakiteko, alderatu biderkadura gurutzatuak.","Se obtienen multiplicando (amplificar) o dividiendo (simplificar) el numerador y el denominador por el mismo número distinto de cero. Para saber si dos fracciones son equivalentes, compara los productos cruzados.","نحصل عليها بضرب البسط والمقام في العدد نفسه غير الصفري (التوسيع) أو بقسمتهما عليه (التبسيط). ولمعرفة هل الكسران متكافئان قارن حاصلَي الضرب التبادلي.","You get them by multiplying (scaling up) or dividing (simplifying) the numerator and the denominator by the same non-zero number. To find out whether two fractions are equivalent, compare the cross products."),examplePrompt:e("$\\frac{6}{14}$ eta $\\frac{9}{21}$ baliokideak dira?","¿Son equivalentes $\\frac{6}{14}$ y $\\frac{9}{21}$?","هل $\\frac{6}{14}$ و$\\frac{9}{21}$ متكافئان؟","Are $\\frac{6}{14}$ and $\\frac{9}{21}$ equivalent?"),example:i("$6\\cdot 21=14\\cdot 9=126$"),exampleAnswer:e("Bai: biderkadura gurutzatuak berdinak dira. Biek $\\frac{3}{7}$ balio dute.","Sí: los productos cruzados son iguales. Las dos valen $\\frac{3}{7}$.","نعم: حاصلا الضرب التبادلي متساويان. وكلاهما يساوي $\\frac{3}{7}$.","Yes: the cross products are equal. Both are worth $\\frac{3}{7}$.")},simplification:{vocabulary:[e("sinplifikatu","simplificar","بسّط","simplify"),e("zatitzaile komuna","divisor común","القاسم المشترك","common divisor")],definitions:[{term:e("Zatiki laburtezina","Fracción irreducible","الكسر غير القابل للاختزال","Fraction in simplest form"),meaning:e("Gehiago sinplifikatu ezin dena: zenbakitzaileak eta izendatzaileak 1 baino ez dute zatitzaile komun.","La que no se puede simplificar más: numerador y denominador solo tienen el 1 como divisor común.","الكسر الذي لا يمكن تبسيطه أكثر: ليس للبسط والمقام قاسم مشترك سوى 1.","One that cannot be simplified any further: the numerator and the denominator only have 1 as a common divisor.")}],explanation:e("Pixkanaka sinplifika daiteke, zatitzaile komun txikiekin zatituz (2, 3, 5…), edo urrats bakarrean, bi gaiak haien ZKH balioarekin zatituz. Zatikia negatiboa bada, zeinua aurrean edo zenbakitzailean idazten da.","Se puede simplificar poco a poco, dividiendo entre divisores comunes pequeños (2, 3, 5…), o en un solo paso, dividiendo los dos términos entre su m.c.d. Si la fracción es negativa, el signo se escribe delante o en el numerador.","يمكن التبسيط تدريجيًا بالقسمة على قواسم مشتركة صغيرة (2، 3، 5…) أو في خطوة واحدة بقسمة الحدّين على قاسمهما المشترك الأكبر. وإذا كان الكسر سالبًا تُكتب الإشارة أمامه أو في البسط.","You can simplify bit by bit, dividing by small common divisors (2, 3, 5…), or in one step, dividing both terms by their GCD. If the fraction is negative, the sign goes in front or on the numerator."),examplePrompt:e("Sinplifikatu $\\frac{60}{84}$ zatiki laburtezina lortu arte.","Simplifica $\\frac{60}{84}$ hasta la fracción irreducible.","بسّط $\\frac{60}{84}$ حتى تصل إلى كسر غير قابل للاختزال.","Simplify $\\frac{60}{84}$ to its simplest form."),example:i("$\\frac{60}{84}=\\frac{30}{42}=\\frac{10}{14}=\\frac{5}{7}$"),exampleAnswer:e("$\\frac{5}{7}$. ZKH balioarekin, 12, urrats bakarrean iristen da.","$\\frac{5}{7}$. Dividiendo entre el m.c.d., 12, se llega en un solo paso.","$\\frac{5}{7}$. وبالقسمة على القاسم المشترك الأكبر 12 نصل في خطوة واحدة.","$\\frac{5}{7}$. Dividing by the GCD, 12, you get there in one step.")},ordering:{vocabulary:[e("izendatzaile komuna","denominador común","المقام المشترك","common denominator"),e("handiagoa","mayor","أكبر","greater"),e("txikiagoa","menor","أصغر","smaller")],explanation:e("Begiratu lehenik zeinuari: zatiki negatibo oro edozein positibo baino txikiagoa da. Izendatzaile berarekin, zenbakitzaile handiena duena da handiena. Desberdinak badira, bihurtu izendatzaile komunera edo alderatu biderkadura gurutzatuak. Negatiboen artean, zerotik hurbilen dagoena da handiena.","Mira primero el signo: toda fracción negativa es menor que cualquier positiva. Con el mismo denominador, es mayor la de mayor numerador. Si son distintos, pásalas a denominador común o compara los productos cruzados. Entre negativas, es mayor la más cercana a 0.","انظر أولًا إلى الإشارة: كل كسر سالب أصغر من أي كسر موجب. ومع المقام نفسه يكون الأكبر صاحب البسط الأكبر. وإذا اختلفت المقامات فحوّلها إلى مقام مشترك أو قارن حاصلَي الضرب التبادلي. وبين السالبة يكون الأكبر الأقرب إلى 0.","First look at the sign: every negative fraction is smaller than any positive one. With the same denominator, the one with the bigger numerator is greater. If they are different, change them to a common denominator or compare the cross products. Between negatives, the one closer to 0 is greater."),examplePrompt:e("Ordenatu txikienetik handienera: $\\frac{3}{4}$, $-\\frac{1}{2}$, $\\frac{2}{3}$ eta $\\frac{7}{12}$.","Ordena de menor a mayor: $\\frac{3}{4}$, $-\\frac{1}{2}$, $\\frac{2}{3}$ y $\\frac{7}{12}$.","رتّب من الأصغر إلى الأكبر: $\\frac{3}{4}$ و$-\\frac{1}{2}$ و$\\frac{2}{3}$ و$\\frac{7}{12}$.","Order from smallest to largest: $\\frac{3}{4}$, $-\\frac{1}{2}$, $\\frac{2}{3}$ and $\\frac{7}{12}$."),example:i("$-\\frac{1}{2}<\\frac{7}{12}<\\frac{2}{3}<\\frac{3}{4}$"),exampleAnswer:e("12 izendatzailearekin: $\\frac{9}{12}$, $\\frac{8}{12}$ eta $\\frac{7}{12}$; negatiboa doa lehenik.","Con denominador 12: $\\frac{9}{12}$, $\\frac{8}{12}$ y $\\frac{7}{12}$; la negativa va primero.","بالمقام 12: $\\frac{9}{12}$ و$\\frac{8}{12}$ و$\\frac{7}{12}$؛ والسالب أولًا.","With denominator 12: $\\frac{9}{12}$, $\\frac{8}{12}$ and $\\frac{7}{12}$; the negative one comes first.")},"add-subtract":{vocabulary:[e("izendatzaile komuna","denominador común","المقام المشترك","common denominator"),e("zenbakitzailea","numerador","البسط","numerator")],why:{text:e("Tamaina bereko zatiak bakarrik zenba daitezke batera, metroak eta zentimetroak batzen ez diren bezala. Herenak eta laurdenak hamabirenetara aldatzen dira, bietan sartzen baitira, eta orduan bai, zenbakitzaileak batzen dira.","Solo se pueden contar juntos trozos del mismo tamaño, igual que no se suman metros con centímetros. Tercios y cuartos se cambian a doceavos, que caben en los dos, y entonces sí se suman los numeradores.","لا نعدّ معًا إلا قطعًا من الحجم نفسه، كما لا نجمع الأمتار مع السنتيمترات. فالأثلاث والأرباع نحوّلها إلى أجزاء من اثني عشر تصلح للاثنين معًا، وعندها نجمع البسوط.","You can only count pieces of the same size together, just as you do not add metres to centimetres. Thirds and quarters are changed into twelfths, which fit both, and then you can add the numerators."),math:i("$\\frac{1}{3}+\\frac{1}{4}=\\frac{4}{12}+\\frac{3}{12}=\\frac{7}{12}$")},explanation:e("Mota bereko zatiak bakarrik batu daitezke. Izendatzaile berarekin, zenbakitzaileak batu edo kentzen dira eta izendatzailea mantentzen da. Desberdinak badira, lehenik izendatzaile komuneko zatiki baliokideak bilatzen dira: txikiena izendatzaileen MKT da.","Solo se pueden sumar trozos del mismo tipo. Con el mismo denominador, se suman o restan los numeradores y el denominador se mantiene. Si son distintos, primero se buscan fracciones equivalentes con un denominador común: el más pequeño es el m.c.m. de los denominadores.","لا تُجمع إلا أجزاء من النوع نفسه. ومع المقام نفسه نجمع البسوط أو نطرحها ونُبقي المقام. وإذا اختلفت نبحث أولًا عن كسور مكافئة بمقام مشترك، وأصغره المضاعف المشترك الأصغر للمقامات.","You can only add pieces of the same kind. With the same denominator, add or subtract the numerators and keep the denominator. If they are different, first find equivalent fractions with a common denominator: the smallest one is the LCM of the denominators."),examplePrompt:e("Kalkulatu $\\frac{2}{3}+\\frac{3}{10}$.","Calcula $\\frac{2}{3}+\\frac{3}{10}$.","احسب $\\frac{2}{3}+\\frac{3}{10}$.","Work out $\\frac{2}{3}+\\frac{3}{10}$."),example:i("$\\frac{2}{3}+\\frac{3}{10}=\\frac{20}{30}+\\frac{9}{30}=\\frac{29}{30}$"),exampleAnswer:e("Izendatzaile komuna 30 da, 3 eta 10 zenbakien MKT.","El denominador común es 30, el m.c.m. de 3 y 10.","المقام المشترك 30، وهو المضاعف المشترك الأصغر لـ3 و10.","The common denominator is 30, the LCM of 3 and 10.")},"multiply-divide":{vocabulary:[e("zeinuen erregela","regla de los signos","قاعدة الإشارات","rule of signs"),e("zatitu","dividir","القسمة","divide")],definitions:[{term:e("Zatiki baten alderantzizkoa","Inversa de una fracción","مقلوب الكسر","Reciprocal"),meaning:e("Gaiak trukatuta ateratzen dena: $\\frac{a}{b}$ zatikiarena $\\frac{b}{a}$ da. Biderkatuta 1 ematen dute.","La que sale al intercambiar sus términos: la de $\\frac{a}{b}$ es $\\frac{b}{a}$. Su producto es 1.","الكسر الناتج عن تبديل الحدّين: مقلوب $\\frac{a}{b}$ هو $\\frac{b}{a}$. وحاصل ضربهما 1.","What you get by swapping the terms: the reciprocal of $\\frac{a}{b}$ is $\\frac{b}{a}$. Their product is 1.")}],why:{text:e("Zatitzea zenbaki bat beste batean zenbat aldiz sartzen den galdetzea da. Unitate bakoitzean bi erdi sartzen dira; beraz, 3 unitatetan 6 sartzen dira: $\\frac{1}{2}$ zatikiaz zatitzea 2 zenbakiaz biderkatzea da, haren alderantzizkoaz.","Dividir es preguntar cuántas veces cabe un número en otro. En cada unidad caben dos medios, así que en 3 caben 6: dividir entre $\\frac{1}{2}$ da lo mismo que multiplicar por 2, su inversa.","القسمة سؤال: كم مرة يدخل عدد في عدد آخر؟ في كل وحدة نصفان، إذن في 3 وحدات 6 أنصاف: القسمة على $\\frac{1}{2}$ تعطي ما يعطيه الضرب في 2، أي في مقلوبه.","Dividing asks how many times one number fits into another. Two halves fit into each whole, so 6 halves fit into 3: dividing by $\\frac{1}{2}$ gives the same as multiplying by 2, its reciprocal."),math:i("$3\\div\\frac{1}{2}=3\\cdot 2=6$")},explanation:e("Biderkatzeko ez da izendatzaile komunik behar: zenbakitzailea bider zenbakitzailea eta izendatzailea bider izendatzailea. Zatiki batez zatitzea haren alderantzizkoaz biderkatzea da. Zeinuen erregela zenbaki osoena bera da.","Para multiplicar no hace falta denominador común: numerador por numerador y denominador por denominador. Dividir entre una fracción es multiplicar por su inversa. La regla de los signos es la misma que con los enteros.","لا نحتاج في الضرب إلى مقام مشترك: البسط في البسط والمقام في المقام. والقسمة على كسر هي الضرب في مقلوبه. وقاعدة الإشارات هي نفسها في الأعداد الصحيحة.","To multiply you do not need a common denominator: numerator times numerator and denominator times denominator. Dividing by a fraction is multiplying by its reciprocal. The rule of signs is the same as for integers."),examplePrompt:e("Kalkulatu $\\frac{9}{10}\\div\\left(-\\frac{3}{5}\\right)$.","Calcula $\\frac{9}{10}\\div\\left(-\\frac{3}{5}\\right)$.","احسب $\\frac{9}{10}\\div\\left(-\\frac{3}{5}\\right)$.","Work out $\\frac{9}{10}\\div\\left(-\\frac{3}{5}\\right)$."),example:i("$\\begin{aligned}\\frac{9}{10}\\div\\left(-\\frac{3}{5}\\right)&=\\frac{9}{10}\\cdot\\left(-\\frac{5}{3}\\right)\\\\&=-\\frac{3}{2}\\end{aligned}$"),exampleAnswer:e("$-\\frac{3}{2}$: bigarrena alderantzikatzen da, eta zeinu desberdinekin emaitza negatiboa da.","$-\\frac{3}{2}$: se invierte la segunda y, con signos distintos, el resultado es negativo.","$-\\frac{3}{2}$: نقلب الثاني، ومع إشارتين مختلفتين تكون النتيجة سالبة.","$-\\frac{3}{2}$: flip the second one, and with different signs the result is negative.")},combined:{vocabulary:[e("parentesia","paréntesis","الأقواس","brackets"),e("ordena","orden","الترتيب","order")],explanation:e("Zatikiekin, eragiketek zenbaki osoekin duten ordena bera dute: parentesiak, berreturak, biderketak eta zatiketak, eta azkenik batuketak eta kenketak. Maila berekoak, ezkerretik eskuinera. Idatzi urrats bakoitza lerro batean.","Con fracciones, las operaciones siguen el mismo orden que con los enteros: paréntesis, potencias, multiplicaciones y divisiones, y por último sumas y restas. Las del mismo nivel, de izquierda a derecha. Escribe cada paso en una línea.","تتبع العمليات على الكسور الترتيب نفسه كما في الأعداد الصحيحة: الأقواس، ثم القوى، ثم الضرب والقسمة، وأخيرًا الجمع والطرح. وما كان من المستوى نفسه فمن اليسار إلى اليمين. اكتب كل خطوة في سطر.","With fractions, operations follow the same order as with integers: brackets, powers, multiplication and division, and finally addition and subtraction. Those of the same level, from left to right. Write each step on its own line."),examplePrompt:e("Kalkulatu $\\frac{1}{2}+\\frac{3}{4}\\cdot\\frac{2}{9}$.","Calcula $\\frac{1}{2}+\\frac{3}{4}\\cdot\\frac{2}{9}$.","احسب $\\frac{1}{2}+\\frac{3}{4}\\cdot\\frac{2}{9}$.","Work out $\\frac{1}{2}+\\frac{3}{4}\\cdot\\frac{2}{9}$."),example:i("$\\begin{aligned}\\frac{1}{2}+\\frac{3}{4}\\cdot\\frac{2}{9}&=\\frac{1}{2}+\\frac{1}{6}\\\\&=\\frac{4}{6}=\\frac{2}{3}\\end{aligned}$"),exampleAnswer:e("$\\frac{2}{3}$. Lehenik biderketa, gero batuketa.","$\\frac{2}{3}$. Primero el producto, después la suma.","$\\frac{2}{3}$. الضرب أولًا ثم الجمع.","$\\frac{2}{3}$. First the product, then the sum.")},powers:{vocabulary:[e("oinarria","base","الأساس","base"),e("berretzailea","exponente","الأس","exponent")],why:{text:e("Berretura bat biderketa errepikatua da, eta zatikiak zenbakitzailea bider zenbakitzailea eta izendatzailea bider izendatzailea biderkatzen dira. Horregatik, berretzailea bi gaiei aplikatzen zaie.","Una potencia es una multiplicación repetida, y las fracciones se multiplican numerador por numerador y denominador por denominador. Por eso el exponente se aplica a los dos términos.","القوة ضرب متكرر، والكسور تُضرب البسط في البسط والمقام في المقام. لذلك يُطبَّق الأس على الحدّين معًا.","A power is a repeated multiplication, and fractions are multiplied numerator by numerator and denominator by denominator. That is why the exponent applies to both terms."),math:i("$\\left(\\frac{2}{3}\\right)^{2}=\\frac{2}{3}\\cdot\\frac{2}{3}=\\frac{2^{2}}{3^{2}}=\\frac{4}{9}$")},explanation:e("Zatiki baten berretura zatikia bere buruarekin hainbat aldiz biderkatzea da; horregatik, zenbakitzailea eta izendatzailea berretzen dira. Oinarria negatiboa bada, berretzaile bikoitiak emaitza positiboa ematen du, eta bakoitiak negatiboa. Parentesiek esaten dute zeinua oinarriaren parte den.","Una potencia de una fracción es multiplicarla por sí misma varias veces; por eso se elevan el numerador y el denominador. Si la base es negativa, un exponente par da resultado positivo, y uno impar, negativo. Los paréntesis dicen si el signo forma parte de la base.","قوة الكسر هي ضربه في نفسه عدة مرات، ولذلك نرفع البسط والمقام. وإذا كان الأساس سالبًا أعطى الأس الزوجي نتيجة موجبة والفردي سالبة. وتبيّن الأقواس هل الإشارة جزء من الأساس.","A power of a fraction means multiplying it by itself several times; that is why both the numerator and the denominator are raised. If the base is negative, an even exponent gives a positive result and an odd one a negative result. The brackets show whether the sign is part of the base."),examplePrompt:e("Kalkulatu $\\left(-\\frac{2}{5}\\right)^{3}$ eta $\\left(\\frac{3}{2}\\right)^{2}$.","Calcula $\\left(-\\frac{2}{5}\\right)^{3}$ y $\\left(\\frac{3}{2}\\right)^{2}$.","احسب $\\left(-\\frac{2}{5}\\right)^{3}$ و$\\left(\\frac{3}{2}\\right)^{2}$.","Work out $\\left(-\\frac{2}{5}\\right)^{3}$ and $\\left(\\frac{3}{2}\\right)^{2}$."),example:i("$\\begin{gathered}\\left(-\\frac{2}{5}\\right)^{3}=-\\frac{8}{125}\\\\\\left(\\frac{3}{2}\\right)^{2}=\\frac{9}{4}\\end{gathered}$"),exampleAnswer:e("Berretzaile bakoitia: zeinua geratu egiten da. 1 baino handiagoa den zatikia handitu egiten da berretzean.","Exponente impar: el signo se queda. Una fracción mayor que 1 crece al elevarla.","الأس فردي: تبقى الإشارة. والكسر الأكبر من 1 يكبر عند رفعه إلى قوة.","Odd exponent: the sign stays. A fraction greater than 1 grows when you raise it.")},"fraction-of":{vocabulary:[e("kantitatea","cantidad","الكمية","quantity"),e("osoa","total","الكل","whole")],explanation:e("Kantitate baten zatikia kalkulatzeko, zatitu kantitatea izendatzailearekin eta biderkatu zenbakitzailearekin: zatikiaz biderkatzea da. Zatia ezaguna bada eta osoa bilatzen bada, aurkitu zati baten balioa eta biderkatu izendatzailearekin.","Para calcular una fracción de una cantidad, divide la cantidad entre el denominador y multiplica por el numerador: es multiplicar por la fracción. Si se conoce la parte y se busca el total, halla el valor de una parte y multiplícalo por el denominador.","لحساب كسر من كمية اقسم الكمية على المقام واضرب في البسط: إنه الضرب في الكسر. وإذا عُرف الجزء وطُلب الكل فأوجد قيمة جزء واحد واضربها في المقام.","To work out a fraction of an amount, divide the amount by the denominator and multiply by the numerator: it is multiplying by the fraction. If you know the part and want the total, find the value of one part and multiply it by the denominator."),examplePrompt:e("Klase bateko 36 ikasleetatik, $\\frac{5}{9}$ autobusez joaten dira ikastetxera. Zenbat dira? Zenbat ez dira autobusez joaten?","De los 36 alumnos de una clase, $\\frac{5}{9}$ van al instituto en autobús. ¿Cuántos son? ¿Cuántos no van en autobús?","من بين 36 تلميذًا في قسم يذهب $\\frac{5}{9}$ إلى المدرسة بالحافلة. كم عددهم؟ وكم لا يذهبون بالحافلة؟","Of the 36 students in a class, $\\frac{5}{9}$ go to school by bus. How many is that? How many do not go by bus?"),example:i("$\\begin{gathered}36\\div 9\\cdot 5=20\\\\36-20=16\\end{gathered}$"),exampleAnswer:e("20 autobusez joaten dira eta 16 ez, hau da, klasearen $\\frac{4}{9}$.","Van 20 en autobús y 16 no, es decir, $\\frac{4}{9}$ de la clase.","يذهب 20 بالحافلة ولا يذهب 16، أي $\\frac{4}{9}$ من القسم.","20 go by bus and 16 do not, that is, $\\frac{4}{9}$ of the class.")},percentages:{vocabulary:[e("zenbaki hamartarra","número decimal","العدد العشري","decimal"),e("hamartar periodikoa","decimal periódico","العدد العشري الدوري","recurring decimal"),e("hurbilketa","aproximación","القيمة التقريبية","approximation")],definitions:[{term:e("Ehunekoa","Porcentaje","النسبة المئوية","Percentage"),meaning:e("100 izendatzailea duen zatikia: %35 ehuneko 35 da.","Una fracción de denominador 100: el 35 % son 35 de cada 100.","كسر مقامه 100: ‏35٪ تعني 35 من كل 100.","A fraction with denominator 100: 35% means 35 out of every 100.")}],explanation:e("Zatiki bat, hamartar bat eta ehuneko bat balio beraren hiru idazkera izan daitezke. Zatikia hamartar bihurtzeko, zatitu zenbakitzailea izendatzailearekin; hamartarretik ehunekora, biderkatu 100 zenbakiarekin. Zatiketa amaitzen ez bada, hamartarra periodikoa da, eta biribiltzean hurbilketa bat idazten da.","Una fracción, un decimal y un porcentaje pueden ser tres formas del mismo valor. Para pasar una fracción a decimal, divide el numerador entre el denominador; del decimal al porcentaje, multiplica por 100. Si la división no termina, el decimal es periódico: al redondear se escribe una aproximación.","يمكن أن يكون الكسر والعدد العشري والنسبة المئوية ثلاث كتابات للقيمة نفسها. لتحويل كسر إلى عدد عشري اقسم البسط على المقام، ومن العشري إلى النسبة المئوية اضرب في 100. وإذا لم تنتهِ القسمة فالعدد العشري دوري، وعند التقريب نكتب قيمة تقريبية.","A fraction, a decimal and a percentage can be three ways of writing the same value. To turn a fraction into a decimal, divide the numerator by the denominator; from the decimal to the percentage, multiply by 100. If the division does not end, the decimal is recurring, and when you round it you write an approximation."),examplePrompt:e("Idatzi $\\frac{7}{20}$ hamartar gisa eta ehuneko gisa.","Escribe $\\frac{7}{20}$ como decimal y como porcentaje.","اكتب $\\frac{7}{20}$ عددًا عشريًا ونسبة مئوية.","Write $\\frac{7}{20}$ as a decimal and as a percentage."),example:i("$\\frac{7}{20}=7\\div 20=0{,}35$"),exampleAnswer:e("$0{,}35\\cdot 100=35$: %35 da.","$0{,}35\\cdot 100=35$: es el 35 %.","$0{,}35\\cdot 100=35$: أي 35٪.","$0{,}35\\cdot 100=35$: it is 35%.")},proportionality:{vocabulary:[e("magnitudea","magnitud","الكمية","quantity"),e("zuzenki proportzionalak","directamente proporcionales","متناسبتان طرديًا","directly proportional"),e("deskontua","descuento","التخفيض","discount")],explanation:e("Bi magnitude zuzenki proportzionalak dira, bat zenbaki batez biderkatzean bestea ere zenbaki berarekin biderkatzen bada; haien zatidura konstantea da. Unitatera laburtuz edo proportzio bat planteatuz ebazten da. Ehuneko bat aplikatzea proportzionaltasun-kasu bat da.","Dos magnitudes son directamente proporcionales si, al multiplicar una por un número, la otra queda multiplicada por el mismo número; su cociente es constante. Se resuelve reduciendo a la unidad o planteando una proporción. Aplicar un porcentaje es un caso de proporcionalidad.","تكون كميتان متناسبتين طرديًا إذا ضُربت إحداهما في عدد فضُربت الأخرى في العدد نفسه، وحاصل قسمتهما ثابت. وتُحل بالرجوع إلى الوحدة أو بكتابة تناسب. وتطبيق نسبة مئوية حالة من حالات التناسب.","Two quantities are directly proportional if, when one is multiplied by a number, the other is multiplied by the same number; their quotient is constant. You solve it by reducing to one unit or by setting up a proportion. Applying a percentage is a case of proportion."),examplePrompt:e("45 €-ko prezio bati %20 deskontatzen zaio. Zenbat euro dira?","A un precio de 45 € se le aplica un descuento del 20 %. ¿Cuántos euros se descuentan?","سعر 45 € عليه تخفيض 20٪. كم يورو يُخصم؟","A 20% discount is applied to a price of €45. How many euros are taken off?"),example:i("$\\frac{20}{100}\\cdot 45=9$"),exampleAnswer:e("9 € deskontatzen dira: 36 € ordaintzen dira.","Se descuentan 9 €: se pagan 36 €.","يُخصم 9 €: فيُدفع 36 €.","€9 is taken off: you pay €36.")}},d=t=>({eu:t,es:t,en:t,ar:t.replace(/\{,\}/g,".")}),v=[{id:"meaning",stage:"meaning",title:{eu:"Zer adierazten du zatiki batek?",es:"¿Qué representa una fracción?",en:"What does a fraction represent?",ar:"ماذا يمثّل الكسر؟"},goal:{eu:"Zatikia zati gisa, zatiketa gisa eta zenbaki gisa interpretatzea.",es:"Interpretar una fracción como parte, como cociente y como número.",en:"Interpret a fraction as a part, as a quotient and as a number.",ar:"تفسير الكسر بوصفه جزءًا وقسمةً وعددًا."},stepsKind:"facts",steps:[{title:{eu:"Osoaren zati bat",es:"Parte de un todo",en:"Part of a whole",ar:"جزء من كل"},text:{eu:"Txokolate-tableta bat 4 zati berdinetan banatu eta 3 hartzen badituzu, tabletaren $\\frac{3}{4}$ hartu duzu.",es:"Si divides una tableta de chocolate en 4 trozos iguales y tomas 3, has tomado $\\frac{3}{4}$ de la tableta.",en:"If you divide a chocolate bar into 4 equal pieces and take 3, you have taken $\\frac{3}{4}$ of the bar.",ar:"إذا قسمت لوح شوكولاتة إلى 4 قطع متساوية وأخذت 3 منها، فقد أخذت $\\frac{3}{4}$ اللوح."}},{title:{eu:"Zatiketa bat",es:"Una división",en:"A division",ar:"قسمة"},text:{eu:"3 pizza 4 lagunen artean banatzen badira, bakoitzak $\\frac{3}{4}$ pizza jaten du. Zatikia zatiketa bat da.",es:"Si se reparten 3 pizzas entre 4 personas, cada una come $\\frac{3}{4}$ de pizza. La fracción es una división.",en:"If 3 pizzas are shared between 4 people, each one eats $\\frac{3}{4}$ of a pizza. The fraction is a division.",ar:"إذا وُزّعت 3 بيتزا على 4 أشخاص، يأكل كل واحد $\\frac{3}{4}$ بيتزا. فالكسر قسمة."},math:d("$\\frac{3}{4}=3\\div 4=0{,}75$")},{title:{eu:"Zenbaki bat",es:"Un número",en:"A number",ar:"عدد"},text:{eu:"$\\frac{3}{4}$ zenbaki-zuzenean dago, 0 eta 1 artean, 1 zenbakitik hurbilago. Zenbakitzailea izendatzailea baino handiagoa bada, zatikiak 1 baino gehiago balio du.",es:"$\\frac{3}{4}$ ocupa un punto de la recta, entre 0 y 1, más cerca de 1. Si el numerador es mayor que el denominador, la fracción vale más que 1.",en:"$\\frac{3}{4}$ is a point on the number line, between 0 and 1, closer to 1. If the numerator is bigger than the denominator, the fraction is worth more than 1.",ar:"يقع $\\frac{3}{4}$ على خط الأعداد بين 0 و1، وهو أقرب إلى 1. وإذا كان البسط أكبر من المقام كانت قيمة الكسر أكبر من 1."},math:"$0<\\frac{3}{4}<1<\\frac{5}{4}$"},{title:{eu:"Zatiak berdinak izan behar dira",es:"Las partes deben ser iguales",en:"The parts must be equal",ar:"يجب أن تكون الأجزاء متساوية"},text:{eu:"Tableta tamaina desberdineko 4 zatitan hausten bada, zati bakoitza ez da laurden bat. Izendatzaileak zati berdinak eskatzen ditu.",es:"Si la tableta se rompe en 4 trozos de distinto tamaño, cada trozo no es un cuarto. El denominador exige partes iguales.",en:"If the bar is broken into 4 pieces of different sizes, each piece is not a quarter. The denominator requires equal parts.",ar:"إذا انكسر اللوح إلى 4 قطع مختلفة الحجم فليست كل قطعة ربعًا. فالمقام يشترط أجزاء متساوية."}}],takeaway:{eu:"Izendatzailea: zenbat zati berdin. Zenbakitzailea: zenbat hartzen diren.",es:"Denominador: en cuántas partes iguales. Numerador: cuántas se toman.",en:"Denominator: into how many equal parts. Numerator: how many are taken.",ar:"المقام: كم جزءًا متساويًا. البسط: كم جزءًا نأخذ."}},{id:"representation",stage:"meaning",figureAfterSteps:!0,title:{eu:"Zatiki propioak, inpropioak eta mistoak",es:"Fracciones propias, impropias y mixtas",en:"Proper, improper and mixed fractions",ar:"الكسور الحقيقية وغير الحقيقية والأعداد الكسرية"},goal:{eu:"Zatiki inpropio bat zenbaki misto bihurtzea eta alderantziz, eta zenbaki-zuzenean kokatzea.",es:"Pasar una fracción impropia a número mixto y al revés, y situarla en la recta.",en:"Convert an improper fraction into a mixed number and back, and place it on the number line.",ar:"تحويل الكسر غير الحقيقي إلى عدد كسري وبالعكس، ووضعه على خط الأعداد."},problem:{eu:"Idatzi $\\frac{17}{5}$ zenbaki misto gisa.",es:"Escribe $\\frac{17}{5}$ como número mixto.",en:"Write $\\frac{17}{5}$ as a mixed number.",ar:"اكتب $\\frac{17}{5}$ عددًا كسريًا."},stepsKind:"steps",steps:[{text:{eu:"Zatitu zenbakitzailea izendatzaileaz.",es:"Divide el numerador entre el denominador.",en:"Divide the numerator by the denominator.",ar:"اقسم البسط على المقام."},math:"$17=5\\cdot 3+2$"},{text:{eu:"Zatidura unitate osoak dira.",es:"El cociente son las unidades completas.",en:"The quotient is the number of whole units.",ar:"الناتج هو عدد الوحدات الكاملة."},math:"$3$"},{text:{eu:"Hondarra soberan dagoen zatiaren zenbakitzailea da; izendatzailea ez da aldatzen.",es:"El resto es el numerador de la parte que sobra; el denominador no cambia.",en:"The remainder is the numerator of the part left over; the denominator stays the same.",ar:"الباقي هو بسط الجزء المتبقي، والمقام لا يتغير."},math:"$\\frac{17}{5}=3\\frac{2}{5}$"},{text:{eu:"Itzultzeko: biderkatu unitateak izendatzaileaz eta batu zenbakitzailea.",es:"Para volver: multiplica las unidades por el denominador y suma el numerador.",en:"To go back: multiply the whole units by the denominator and add the numerator.",ar:"للعودة: اضرب الوحدات في المقام وأضف البسط."},math:"$3\\frac{2}{5}=\\frac{3\\cdot 5+2}{5}=\\frac{17}{5}$"}],takeaway:{eu:"Adierazpena aldatzen da; balioa ez.",es:"Cambia la representación, no el valor.",en:"The way it is written changes, not the value.",ar:"يتغيّر التمثيل ولا تتغيّر القيمة."}},{id:"equivalence",stage:"equivalence",title:{eu:"Zatiki baliokideak",es:"Fracciones equivalentes",en:"Equivalent fractions",ar:"الكسور المتكافئة"},goal:{eu:"Itxura desberdina baina balio bera duten zatikiak sortzea eta ezagutzea.",es:"Construir y reconocer fracciones con distinta apariencia y el mismo valor.",en:"Build and recognise fractions that look different but have the same value.",ar:"تكوين الكسور المختلفة في الشكل والمتساوية في القيمة والتعرّف عليها."},stepsKind:"facts",steps:[{title:{eu:"Anplifikatu",es:"Amplificar",en:"Expanding",ar:"التوسيع"},text:{eu:"Biderkatu bi gaiak zenbaki berarekin: zatiak txikiagoak dira, baina gehiago hartzen dituzu.",es:"Multiplica los dos términos por el mismo número: los trozos son más pequeños, pero tomas más.",en:"Multiply both terms by the same number: the pieces are smaller, but you take more of them.",ar:"اضرب الحدّين في العدد نفسه: تصغر الأجزاء لكنك تأخذ عددًا أكبر منها."},math:"$\\frac{3}{4}=\\frac{3\\cdot 2}{4\\cdot 2}=\\frac{6}{8}$"},{title:{eu:"Sinplifikatu",es:"Simplificar",en:"Simplify",ar:"التبسيط"},text:{eu:"Zatitu bi gaiak zatitzaile komun batez.",es:"Divide los dos términos entre un divisor común.",en:"Divide both terms by a common divisor.",ar:"اقسم الحدّين على قاسم مشترك."},math:"$\\frac{45}{60}=\\frac{45\\div 15}{60\\div 15}=\\frac{3}{4}$"},{title:{eu:"Biderkadura gurutzatuak",es:"Productos cruzados",en:"Cross products",ar:"الضرب التبادلي"},text:{eu:"$\\frac{a}{b}$ eta $\\frac{c}{d}$ baliokideak dira $a\\cdot d=b\\cdot c$ denean.",es:"$\\frac{a}{b}$ y $\\frac{c}{d}$ son equivalentes cuando $a\\cdot d=b\\cdot c$.",en:"$\\frac{a}{b}$ and $\\frac{c}{d}$ are equivalent when $a\\cdot d=b\\cdot c$.",ar:"يتكافأ $\\frac{a}{b}$ و$\\frac{c}{d}$ عندما $a\\cdot d=b\\cdot c$."},math:"$6\\cdot 12=8\\cdot 9=72\\ \\Rightarrow\\ \\frac{6}{8}=\\frac{9}{12}$"},{title:{eu:"Kontuz: batzeak ez du balio",es:"Cuidado: sumar no sirve",en:"Careful: adding does not work",ar:"انتبه: الجمع لا يصلح"},text:{eu:"Bi gaiei zenbaki bera batuz gero, balioa aldatzen da.",es:"Si sumas el mismo número a los dos términos, el valor cambia.",en:"If you add the same number to both terms, the value changes.",ar:"إذا أضفت العدد نفسه إلى الحدّين تتغير القيمة."},math:"$\\frac{1+1}{2+1}=\\frac{2}{3}\\neq\\frac{1}{2}$"}],takeaway:{eu:"Zenbaki bera goian eta behean, biderkatuz edo zatituz: balioa ez da aldatzen.",es:"El mismo número arriba y abajo, multiplicando o dividiendo: el valor no cambia.",en:"Multiplying or dividing the top and bottom by the same number: the value does not change.",ar:"العدد نفسه في الأعلى والأسفل، ضربًا أو قسمةً: القيمة لا تتغير."}},{id:"simplification",stage:"equivalence",needs:[{unit:"dbh2/divisibilidad",topic:"gcd",title:{eu:"Zatitzaile komunetako handiena (ZKH)",es:"Máximo común divisor (m.c.d.)",en:"Greatest common divisor (GCD)",ar:"القاسم المشترك الأكبر (ق.م.أ · ZKH)"}}],figureAfterSteps:!0,title:{eu:"Sinplifikazioa eta zatiki laburtezina",es:"Simplificación y fracción irreducible",en:"Simplifying and the simplest form",ar:"التبسيط والكسر غير القابل للاختزال"},goal:{eu:"Zatiki bat bere forma laburrenean idaztea, urratsez urrats edo ZKHrekin.",es:"Escribir una fracción en su forma más reducida, paso a paso o con el m.c.d.",en:"Write a fraction in its simplest form, step by step or using the GCD.",ar:"كتابة الكسر في أبسط صورة، خطوة بخطوة أو باستعمال ق.م.أ."},problem:{eu:"Sinplifikatu $\\frac{-84}{126}$ zatiki laburtezina lortu arte.",es:"Simplifica $\\frac{-84}{126}$ hasta obtener la fracción irreducible.",en:"Simplify $\\frac{-84}{126}$ until you get the fraction in its simplest form.",ar:"بسّط $\\frac{-84}{126}$ إلى أبسط صورة."},stepsKind:"steps",steps:[{text:{eu:"Kalkulatu zenbakitzailearen eta izendatzailearen ZKH (zeinurik gabe).",es:"Calcula el m.c.d. del numerador y del denominador (sin el signo).",en:"Calculate the GCD of the numerator and the denominator (without the sign).",ar:"احسب ق.م.أ للبسط والمقام (من دون الإشارة)."},math:$("$@GCD(84,126)=42$")},{text:{eu:"Zatitu bi gaiak ZKHz.",es:"Divide los dos términos entre el m.c.d.",en:"Divide both terms by the GCD.",ar:"اقسم الحدّين على ق.م.أ."},math:"$\\frac{-84}{126}=\\frac{-84\\div 42}{126\\div 42}=\\frac{-2}{3}$"},{text:{eu:"Egiaztatu: 2 eta 3 zenbakiek 1 baino ez dute zatitzaile komun. Zatiki laburtezina da.",es:"Comprueba: 2 y 3 solo tienen el 1 como divisor común. Es irreducible.",en:"Check: 2 and 3 only have 1 as a common divisor. It is in its simplest form.",ar:"تحقّق: لا قاسم مشتركًا لـ 2 و3 سوى 1. فالكسر غير قابل للاختزال."},math:"$-\\frac{2}{3}$"}],takeaway:{eu:"Sinplifikatu azken emaitza beti. ZKHrekin urrats bakarrean iristen zara.",es:"Simplifica siempre el resultado final. Con el m.c.d. llegas en un solo paso.",en:"Always simplify the final result. With the GCD you get there in one step.",ar:"بسّط النتيجة النهائية دائمًا. وبالقاسم المشترك الأكبر تصل في خطوة واحدة."}},{id:"ordering",stage:"ordering",needs:[{unit:"dbh2/numeros-enteros",topic:"compare",title:{eu:"Zenbaki osoak alderatzea",es:"Comparar números enteros",en:"Compare integers",ar:"مقارنة الأعداد الصحيحة"}}],title:{eu:"Konparazioa eta ordena",es:"Comparación y orden",en:"Comparison and order",ar:"المقارنة والترتيب"},goal:{eu:"Zatiki positiboak eta negatiboak estrategia egokiaz alderatzea eta ordenatzea.",es:"Comparar y ordenar fracciones positivas y negativas eligiendo una estrategia adecuada.",en:"Compare and order positive and negative fractions by choosing a suitable strategy.",ar:"مقارنة الكسور الموجبة والسالبة وترتيبها باختيار استراتيجية مناسبة."},stepsKind:"facts",steps:[{title:{eu:"Izendatzaile bera",es:"Mismo denominador",en:"Same denominator",ar:"المقام نفسه"},text:{eu:"Zati mota bera: zenbat eta gehiago hartu, handiagoa.",es:"Mismo tipo de trozo: cuantos más tomes, mayor.",en:"Same type of piece: the more you take, the bigger the fraction.",ar:"الأجزاء من النوع نفسه: كلما أخذت أكثر كان الكسر أكبر."},math:"$\\frac{3}{7}<\\frac{5}{7}$"},{title:{eu:"Zenbakitzaile bera",es:"Mismo numerador",en:"Same numerator",ar:"البسط نفسه"},text:{eu:"Izendatzailea zenbat eta txikiagoa, orduan eta handiagoak zatiak.",es:"Cuanto menor es el denominador, más grandes son los trozos.",en:"The smaller the denominator, the bigger the pieces.",ar:"كلما صغر المقام كبرت الأجزاء."},math:"$\\frac{2}{3}>\\frac{2}{5}$"},{title:{eu:"Izendatzaile komuna",es:"Denominador común",en:"Common denominator",ar:"مقام مشترك"},text:{eu:"Bihurtu biak izendatzaile berera eta alderatu zenbakitzaileak.",es:"Pasa las dos al mismo denominador y compara los numeradores.",en:"Change both to the same denominator and compare the numerators.",ar:"حوّل الكسرين إلى المقام نفسه وقارن البسطين."},math:"$\\frac{5}{6}=\\frac{15}{18}>\\frac{14}{18}=\\frac{7}{9}$"},{title:{eu:"Negatiboak",es:"Negativas",en:"Negative",ar:"الكسور السالبة"},text:{eu:"$\\frac{2}{3}<\\frac{3}{4}$ denez, $-\\frac{2}{3}$ zerotik hurbilago dago eta handiagoa da.",es:"Como $\\frac{2}{3}<\\frac{3}{4}$, $-\\frac{2}{3}$ está más cerca de 0 y es mayor.",en:"As $\\frac{2}{3}<\\frac{3}{4}$, $-\\frac{2}{3}$ is closer to 0 and is bigger.",ar:"بما أن $\\frac{2}{3}<\\frac{3}{4}$ فإن $-\\frac{2}{3}$ أقرب إلى 0 وهو الأكبر."},math:"$-\\frac{3}{4}<-\\frac{2}{3}$"},{title:{eu:"Beti dago beste bat tartean",es:"Siempre hay otra en medio",en:"There is always another one in between",ar:"يوجد دائمًا كسر بينهما"},text:{eu:"Bi zatiki desberdinen artean beti dago beste bat. Eraman izendatzaile komunera; tartean hutsunerik ez badago, bikoiztu bien gaiak.",es:"Entre dos fracciones distintas siempre hay otra. Pásalas a denominador común; si no queda hueco en medio, multiplica por 2 los términos de las dos.",en:"Between two different fractions there is always another one. Change them to a common denominator; if there is no gap in between, multiply both terms of both fractions by 2.",ar:"بين كسرين مختلفين يوجد دائمًا كسر آخر. حوّلهما إلى مقام مشترك، وإن لم يبقَ فراغ بينهما فاضرب حدّي كل منهما في 2."},math:"$\\frac{1}{3}=\\frac{4}{12}<\\frac{5}{12}<\\frac{6}{12}=\\frac{1}{2}$"}],takeaway:{eu:"Metodoa baino garrantzitsuagoa da konparazioa arrazoitzea.",es:"Más importante que el método es poder justificar la comparación.",en:"More important than the method is being able to justify the comparison.",ar:"الأهم من الطريقة هو القدرة على تبرير المقارنة."}},{id:"add-subtract",stage:"operations",needs:[{unit:"dbh2/divisibilidad",topic:"lcm",title:{eu:"Multiplo komunetako txikiena (MKT)",es:"Mínimo común múltiplo (m.c.m.)",en:"Least common multiple (LCM)",ar:"المضاعف المشترك الأصغر (م.م.أ · MKT)"}}],title:{eu:"Batuketa eta kenketa",es:"Suma y resta",en:"Addition and subtraction",ar:"الجمع والطرح"},goal:{eu:"Izendatzaile komun egokia aukeratu eta zeinuekin zuzen jardutea.",es:"Elegir un denominador común adecuado y operar correctamente con signos.",en:"Choose a suitable common denominator and work correctly with signs.",ar:"اختيار مقام مشترك مناسب وإجراء العمليات بالإشارات الصحيحة."},problem:{eu:"Kalkulatu $\\frac{5}{6}-\\frac{1}{4}$.",es:"Calcula $\\frac{5}{6}-\\frac{1}{4}$.",en:"Calculate $\\frac{5}{6}-\\frac{1}{4}$.",ar:"احسب $\\frac{5}{6}-\\frac{1}{4}$."},stepsKind:"steps",steps:[{text:{eu:"Kalkulatu izendatzaileen MKT: hori izango da izendatzaile komuna.",es:"Calcula el m.c.m. de los denominadores: será el denominador común.",en:"Calculate the LCM of the denominators: it will be the common denominator.",ar:"احسب م.م.أ للمقامات: سيكون هو المقام المشترك."},math:$("$@LCM(6,4)=12$")},{text:{eu:"Bihurtu zatiki bakoitza izendatzaile hori duen baliokide batean.",es:"Convierte cada fracción en una equivalente con ese denominador.",en:"Convert each fraction into an equivalent one with that denominator.",ar:"حوّل كل كسر إلى كسر مكافئ بهذا المقام."},math:"$\\frac{5}{6}=\\frac{10}{12}\\qquad\\frac{1}{4}=\\frac{3}{12}$"},{text:{eu:"Batu edo kendu zenbakitzaileak; izendatzailea ez da aldatzen.",es:"Suma o resta los numeradores; el denominador no cambia.",en:"Add or subtract the numerators; the denominator does not change.",ar:"اجمع البسوط أو اطرحها، والمقام لا يتغير."},math:"$\\frac{10}{12}-\\frac{3}{12}=\\frac{10-3}{12}=\\frac{7}{12}$"},{text:{eu:"Sinplifikatu, ahal bada. 7 eta 12 zenbakiek ez dute zatitzaile komunik: zatiki laburtezina da.",es:"Simplifica, si se puede. 7 y 12 no tienen divisores comunes: ya es irreducible.",en:"Simplify, if you can. 7 and 12 have no common divisors: it is already in its simplest form.",ar:"بسّط إن أمكن. لا قاسم مشتركًا لـ 7 و12، فالكسر في أبسط صورة."},math:"$\\frac{7}{12}$"}],takeaway:{eu:"Izendatzaile komuna lehenik; sinplifikazioa azkenik. Izendatzaileak ez dira batzen.",es:"Denominador común primero; simplificación al final. Los denominadores no se suman.",en:"Common denominator first; simplify at the end. The denominators are not added.",ar:"المقام المشترك أولًا، والتبسيط أخيرًا. لا نجمع المقامات."}},{id:"multiply-divide",stage:"operations",needs:[{unit:"dbh2/numeros-enteros",topic:"multiply-divide",title:{eu:"Biderketa eta zatiketa: zeinuen araua",es:"Producto y cociente: regla de los signos",en:"Product and quotient: rule of signs",ar:"الضرب والقسمة: قاعدة الإشارات"}}],title:{eu:"Biderketa eta zatiketa",es:"Multiplicación y división",en:"Multiplication and division",ar:"الضرب والقسمة"},goal:{eu:"Zatikiak biderkatzea eta zatitzea, aurretik sinplifikatuz eta alderantzizkoa erabiliz.",es:"Multiplicar y dividir fracciones, simplificando antes y usando la inversa.",en:"Multiply and divide fractions, simplifying first and using the reciprocal.",ar:"ضرب الكسور وقسمتها مع الاختصار المسبق واستعمال المقلوب."},stepsKind:"facts",steps:[{title:{eu:"Biderkatu",es:"Multiplicar",en:"Multiply",ar:"الضرب"},text:{eu:"Goikoak elkarren artean, behekoak elkarren artean.",es:"Los de arriba entre sí y los de abajo entre sí.",en:"Multiply the tops together and the bottoms together.",ar:"البسط في البسط، والمقام في المقام."},math:"$\\frac{2}{3}\\cdot\\frac{3}{4}=\\frac{2\\cdot 3}{3\\cdot 4}=\\frac{6}{12}=\\frac{1}{2}$"},{title:{eu:"Sinplifikatu aurretik",es:"Simplifica antes",en:"Simplify first",ar:"اختصر قبل الضرب"},text:{eu:"Zenbakitzaile batek eta izendatzaile batek zatitzaile komuna badute, zatitu biderkatu aurretik: zenbakiak txikiak geratzen dira.",es:"Si un numerador y un denominador tienen un divisor común, divide antes de multiplicar: los números se quedan pequeños.",en:"If a numerator and a denominator have a common divisor, divide before multiplying: the numbers stay small.",ar:"إذا كان لبسطٍ ومقامٍ قاسم مشترك فاقسمهما قبل الضرب لتبقى الأعداد صغيرة."},math:"$\\frac{4}{9}\\cdot\\frac{15}{8}=\\frac{1\\cdot 5}{3\\cdot 2}=\\frac{5}{6}$"},{title:{eu:"Alderantzizkoa",es:"La inversa",en:"The reciprocal",ar:"المقلوب"},text:{eu:"$\\frac{a}{b}$-ren alderantzizkoa $\\frac{b}{a}$ da. 0 zenbakiak ez du alderantzizkorik.",es:"La inversa de $\\frac{a}{b}$ es $\\frac{b}{a}$. El 0 no tiene inversa.",en:"The reciprocal of $\\frac{a}{b}$ is $\\frac{b}{a}$. Zero has no reciprocal.",ar:"مقلوب $\\frac{a}{b}$ هو $\\frac{b}{a}$. والصفر ليس له مقلوب."},math:"$\\frac{8}{15}\\cdot\\frac{15}{8}=1$"},{title:{eu:"Zatitu",es:"Dividir",en:"Divide",ar:"القسمة"},text:{eu:"Zenbat zortziren sartzen dira $\\frac{3}{4}$ zatikian? Sei. Zatitzea alderantzizkoaz biderkatzea da.",es:"¿Cuántos octavos caben en $\\frac{3}{4}$? Seis. Dividir es multiplicar por la inversa.",en:"How many eighths fit into $\\frac{3}{4}$? Six. Dividing is multiplying by the reciprocal.",ar:"كم ثُمنًا في $\\frac{3}{4}$؟ ستة. فالقسمة ضرب في المقلوب."},math:"$\\frac{3}{4}\\div\\frac{1}{8}=\\frac{3}{4}\\cdot\\frac{8}{1}=6$"}],takeaway:{eu:"Zatitzeko: alderantzikatu bigarrena eta biderkatu.",es:"Para dividir: invierte la segunda y multiplica.",en:"To divide: flip the second fraction and multiply.",ar:"للقسمة: اقلب الكسر الثاني ثم اضرب."}},{id:"combined",stage:"operations",needs:[{unit:"dbh2/numeros-enteros",topic:"combined",title:{eu:"Eragiketa konbinatuak eta kako zuzenak",es:"Operaciones combinadas y corchetes",en:"Combined operations and square brackets",ar:"العمليات المركبة والأقواس المعقوفة"}}],title:{eu:"Eragiketa konbinatuak",es:"Operaciones combinadas",en:"Combined operations",ar:"العمليات المركبة"},goal:{eu:"Eragiketen hierarkia errespetatuz kalkulatzea.",es:"Calcular respetando la jerarquía de operaciones.",en:"Calculate following the order of operations.",ar:"الحساب مع احترام ترتيب العمليات."},problem:{eu:"Kalkulatu $\\left(\\frac{1}{2}-\\frac{1}{3}\\right)\\cdot 3+\\left(\\frac{1}{2}\\right)^{2}$.",es:"Calcula $\\left(\\frac{1}{2}-\\frac{1}{3}\\right)\\cdot 3+\\left(\\frac{1}{2}\\right)^{2}$.",en:"Calculate $\\left(\\frac{1}{2}-\\frac{1}{3}\\right)\\cdot 3+\\left(\\frac{1}{2}\\right)^{2}$.",ar:"احسب $\\left(\\frac{1}{2}-\\frac{1}{3}\\right)\\cdot 3+\\left(\\frac{1}{2}\\right)^{2}$."},stepsKind:"steps",steps:[{title:{eu:"Parentesiak",es:"Paréntesis",en:"Brackets",ar:"الأقواس"},text:{eu:"Lehenik, parentesien barrukoa.",es:"Primero, lo que hay dentro de los paréntesis.",en:"First, what is inside the parentheses.",ar:"أولًا ما بداخل الأقواس."},math:"$\\frac{1}{2}-\\frac{1}{3}=\\frac{1}{6}$"},{title:{eu:"Berreturak",es:"Potencias",en:"Powers",ar:"القوى"},text:{eu:"Gero, berreturak.",es:"Después, las potencias.",en:"Then, the powers.",ar:"ثم القوى."},math:"$\\left(\\frac{1}{2}\\right)^{2}=\\frac{1}{4}$"},{title:{eu:"Biderketak eta zatiketak",es:"Multiplicaciones y divisiones",en:"Multiplication and division",ar:"الضرب والقسمة"},text:{eu:"Ezkerretik eskuinera.",es:"De izquierda a derecha.",en:"From left to right.",ar:"من اليسار إلى اليمين."},math:"$\\frac{1}{6}\\cdot 3=\\frac{1}{2}$"},{title:{eu:"Batuketak eta kenketak",es:"Sumas y restas",en:"Adding and subtracting",ar:"الجمع والطرح"},text:{eu:"Azkenik, ezkerretik eskuinera.",es:"Por último, de izquierda a derecha.",en:"Last, from left to right.",ar:"وأخيرًا من اليسار إلى اليمين."},math:"$\\frac{1}{2}+\\frac{1}{4}=\\frac{3}{4}$"}],takeaway:{eu:"Ez egin dena batera: idatzi tarteko urratsak.",es:"No lo hagas todo de una vez: escribe los pasos intermedios.",en:"Do not do it all at once: write the intermediate steps.",ar:"لا تنجز كل شيء دفعة واحدة؛ اكتب الخطوات الوسيطة."}},{id:"powers",stage:"operations",needs:[{unit:"dbh1/zenbaki-naturalak",topic:"powers",title:{eu:"Berreturak",es:"Las potencias",en:"Powers",ar:"القوى"}}],title:{eu:"Zatikien berreturak",es:"Potencias de fracciones",en:"Powers of fractions",ar:"قوى الكسور"},goal:{eu:"Zatiki bat berretzea, oinarriaren zeinua eta berretzailearen paritatea kontrolatuz.",es:"Elevar una fracción a una potencia controlando el signo de la base y la paridad del exponente.",en:"Raise a fraction to a power, checking the sign of the base and whether the exponent is even or odd.",ar:"رفع كسر إلى قوة مع ضبط إشارة الأساس وزوجية الأس."},stepsKind:"facts",steps:[{title:{eu:"Gaiak berretu",es:"Se elevan los dos términos",en:"Both terms are raised to the power",ar:"نرفع الحدّين"},text:{eu:"Hiru aldiz biderkatu, beraz goian $2^{3}$ eta behean $3^{3}$.",es:"Se multiplica tres veces, así que arriba queda $2^{3}$ y abajo $3^{3}$.",en:"It is multiplied three times, so the top becomes $2^{3}$ and the bottom $3^{3}$.",ar:"نضرب ثلاث مرات، فيصبح في الأعلى $2^{3}$ وفي الأسفل $3^{3}$."},math:"$\\left(\\frac{2}{3}\\right)^{3}=\\frac{2}{3}\\cdot\\frac{2}{3}\\cdot\\frac{2}{3}=\\frac{8}{27}$"},{title:{eu:"Berretzaile bikoitia",es:"Exponente par",en:"Even exponent",ar:"أس زوجي"},text:{eu:"Bi negatibo biderkatuta, positiboa.",es:"Dos negativos multiplicados dan positivo.",en:"Two negatives multiplied give a positive.",ar:"حاصل ضرب سالبين موجب."},math:"$\\left(-\\frac{3}{5}\\right)^{2}=\\frac{9}{25}$"},{title:{eu:"Berretzaile bakoitia",es:"Exponente impar",en:"Odd exponent",ar:"أس فردي"},text:{eu:"Zeinua negatiboa geratzen da.",es:"El signo queda negativo.",en:"The sign stays negative.",ar:"تبقى الإشارة سالبة."},math:"$\\left(-\\frac{1}{2}\\right)^{3}=-\\frac{1}{8}$"},{title:{eu:"Parentesirik gabe",es:"Sin paréntesis",en:"Without brackets",ar:"من دون أقواس"},text:{eu:"Zeinua ez da berretzen: aurrean geratzen da.",es:"El signo no se eleva: se queda delante.",en:"The sign is not raised: it stays in front.",ar:"الإشارة لا تُرفع إلى القوة بل تبقى في الأمام."},math:"$-\\left(\\frac{3}{5}\\right)^{2}=-\\frac{9}{25}$"}],takeaway:{eu:"Zatiki propio positibo bat berretzean, txikiagoa egiten da: $\\left(\\frac{2}{3}\\right)^{2}=\\frac{4}{9}<\\frac{2}{3}$.",es:"Al elevar una fracción propia positiva, se hace más pequeña: $\\left(\\frac{2}{3}\\right)^{2}=\\frac{4}{9}<\\frac{2}{3}$.",en:"When you raise a positive proper fraction to a power, it gets smaller: $\\left(\\frac{2}{3}\\right)^{2}=\\frac{4}{9}<\\frac{2}{3}$.",ar:"عند رفع كسر حقيقي موجب إلى قوة يصغر: $\\left(\\frac{2}{3}\\right)^{2}=\\frac{4}{9}<\\frac{2}{3}$."}},{id:"fraction-of",stage:"proportionality",title:{eu:"Kantitate baten zatikia",es:"Fracción de una cantidad",en:"Fraction of a quantity",ar:"كسر من كمية"},goal:{eu:"Zati bat, guztizkoa edo falta den kantitatea aurkitzea.",es:"Encontrar una parte, el total o la cantidad que falta.",en:"Find a part, the total or the amount that is missing.",ar:"إيجاد الجزء أو الكل أو الكمية الناقصة."},stepsKind:"facts",steps:[{title:{eu:"Zatia",es:"La parte",en:"The part",ar:"الجزء"},text:{eu:"120 zenbakiaren $\\frac{3}{8}$: zortziren bat 15 da, eta hiru, 45.",es:"$\\frac{3}{8}$ de 120: un octavo es 15 y tres octavos, 45.",en:"$\\frac{3}{8}$ of 120: one eighth is 15 and three eighths are 45.",ar:"$\\frac{3}{8}$ من 120: الثُّمن 15، وثلاثة أثمان 45."},math:{eu:"$\\frac{3}{8}\\cdot 120=\\frac{3\\cdot 120}{8}=45$",es:"$\\frac{3}{8}\\text{ de }120=\\frac{3\\cdot 120}{8}=45$",en:"$\\frac{3}{8}\\text{ of }120=\\frac{3\\cdot 120}{8}=45$",ar:"$\\frac{3}{8}\\cdot 120=\\frac{3\\cdot 120}{8}=45$"}},{title:{eu:"Guztizkoa",es:"El total",en:"The total",ar:"الكل"},text:{eu:"$\\frac{3}{8}$ 45 badira, zortziren bat $45\\div 3=15$ da, eta osoa $8\\cdot 15=120$.",es:"Si $\\frac{3}{8}$ son 45, un octavo es $45\\div 3=15$ y el total, $8\\cdot 15=120$.",en:"If $\\frac{3}{8}$ is 45, one eighth is $45\\div 3=15$ and the total is $8\\cdot 15=120$.",ar:"إذا كان $\\frac{3}{8}$ يساوي 45 فالثُّمن $45\\div 3=15$ والكل $8\\cdot 15=120$."},math:"$45\\div\\frac{3}{8}=120$"},{title:{eu:"Falta dena",es:"Lo que queda",en:"What is left",ar:"المتبقي"},text:{eu:"$\\frac{3}{8}$ gastatu bada, $\\frac{5}{8}$ geratzen da.",es:"Si se ha gastado $\\frac{3}{8}$, queda $\\frac{5}{8}$.",en:"If $\\frac{3}{8}$ has been spent, $\\frac{5}{8}$ is left.",ar:"إذا صُرف $\\frac{3}{8}$ يبقى $\\frac{5}{8}$."},math:"$1-\\frac{3}{8}=\\frac{5}{8}\\qquad\\frac{5}{8}\\cdot 120=75$"},{title:{eu:"Zatiki baten zatikia",es:"Fracción de una fracción",en:"Fraction of a fraction",ar:"كسر من كسر"},text:{eu:"$\\frac{3}{4}$ zatikiaren erdia: zatikiak biderkatzen dira.",es:"La mitad de $\\frac{3}{4}$: se multiplican las fracciones.",en:"Half of $\\frac{3}{4}$: multiply the fractions.",ar:"نصف $\\frac{3}{4}$: نضرب الكسرين."},math:"$\\frac{1}{2}\\cdot\\frac{3}{4}=\\frac{3}{8}$"}],takeaway:{eu:"Identifikatu galderak zatia ala guztizkoa eskatzen duen.",es:"Identifica si la pregunta pide la parte o el total.",en:"Identify whether the question asks for the part or the total.",ar:"حدّد هل المطلوب هو الجزء أم الكل."}},{id:"percentages",stage:"proportionality",needs:[{unit:"dbh1/numeros-decimales",topic:"fraction-division",title:{eu:"Zatikia zatiketa gisa: zehatza edo periodikoa",es:"La fracción como división: exacto o periódico",en:"A fraction as a division: terminating or recurring",ar:"الكسر قسمةً: منتهٍ أو دوري"}}],title:{eu:"Zatikiak, hamartarrak eta ehunekoak",es:"Fracciones, decimales y porcentajes",en:"Fractions, decimals and percentages",ar:"الكسور والأعداد العشرية والنسب المئوية"},goal:{eu:"Hiru adierazpenen artean zehaztasuna galdu gabe bihurtzea.",es:"Convertir entre las tres representaciones sin perder exactitud.",en:"Convert between the three forms without losing accuracy.",ar:"التحويل بين التمثيلات الثلاثة من دون فقدان الدقة."},stepsKind:"facts",steps:[{title:{eu:"Zatikia → hamartarra",es:"Fracción → decimal",en:"Fraction → decimal",ar:"كسر ← عدد عشري"},text:{eu:"Zatitu zenbakitzailea izendatzaileaz.",es:"Divide el numerador entre el denominador.",en:"Divide the numerator by the denominator.",ar:"اقسم البسط على المقام."},math:d("$\\frac{3}{8}=3\\div 8=0{,}375$")},{title:{eu:"Hamartarra → ehunekoa",es:"Decimal → porcentaje",en:"Decimal → percentage",ar:"عدد عشري ← نسبة مئوية"},text:{eu:"Biderkatu 100 zenbakiaz.",es:"Multiplica por 100.",en:"Multiply by 100.",ar:"اضرب في 100."},math:{eu:"$0{,}375\\cdot 100=\\%\\,37{,}5$",es:"$0{,}375\\cdot 100=37{,}5\\,\\%$",en:"$0{,}375\\cdot 100=37{,}5\\,\\%$",ar:"$0.375\\cdot 100=37.5\\,\\%$"}},{title:{eu:"Ehunekoa → zatikia",es:"Porcentaje → fracción",en:"Percentage → fraction",ar:"نسبة مئوية ← كسر"},text:{eu:"Idatzi 100 izendatzailearekin eta sinplifikatu.",es:"Escríbelo sobre 100 y simplifica.",en:"Write it over 100 and simplify.",ar:"اكتبها على 100 ثم بسّط."},math:{eu:"$\\%\\,35=\\frac{35}{100}=\\frac{7}{20}$",es:"$35\\,\\%=\\frac{35}{100}=\\frac{7}{20}$",en:"$35\\,\\%=\\frac{35}{100}=\\frac{7}{20}$",ar:"$35\\,\\%=\\frac{35}{100}=\\frac{7}{20}$"}},{title:{eu:"Periodikoak",es:"Periódicos",en:"Recurring",ar:"الأعداد الدورية"},text:{eu:"$\\frac{1}{3}$ ez da 0,33: 3 zifra amaigabe errepikatzen da. 0,33 hurbilketa da.",es:"$\\frac{1}{3}$ no es 0,33: la cifra 3 se repite sin fin. 0,33 es una aproximación.",en:"$\\frac{1}{3}$ is not 0.33: the digit 3 repeats forever. 0.33 is an approximation.",ar:"$\\frac{1}{3}$ ليس 0.33: يتكرر الرقم 3 بلا نهاية، و0.33 قيمة تقريبية."},math:d("$\\frac{1}{3}=0{,}\\overline{3}\\approx 0{,}33$")},{title:{eu:"Zehatza, hutsa ala mistoa",es:"Exacto, puro o mixto",en:"Exact, pure or mixed",ar:"منتهٍ أم دوري بحت أم مختلط"},text:{eu:"Sinplifikatu eta deskonposatu izendatzailea. 2 eta 5 bakarrik: zehatza. Ez 2 ez 5: periodiko hutsa (periodoa komaren ondoren hasten da). 2 edo 5 eta beste faktore bat: periodiko mistoa (lehenik aurreperiodoa).",es:"Simplifica y descompón el denominador. Solo 2 y 5: exacto. Ni 2 ni 5: periódico puro (el periodo empieza justo después de la coma). 2 o 5 y otro factor: periódico mixto (primero va el anteperiodo).",en:"Simplify and do the prime factorisation of the denominator. Only 2s and 5s: exact. Neither 2 nor 5: pure recurring (the repeating part starts right after the decimal point). 2 or 5 and another factor: mixed recurring (the non-repeating part comes first).",ar:"اختزل الكسر وحلّل المقام. 2 و5 فقط: منتهٍ. لا 2 ولا 5: دوري بحت (يبدأ الدور بعد الفاصلة مباشرة). 2 أو 5 مع عامل آخر: دوري مختلط (يأتي ما قبل الدور أولًا)."},math:d("$\\frac{3}{8}=0{,}375\\quad \\frac{2}{3}=0{,}\\overline{6}\\quad \\frac{5}{6}=0{,}8\\overline{3}$")}],takeaway:{eu:"“=” eta “≈” ez dira gauza bera.",es:"“=” y “≈” no significan lo mismo.",en:"“=” and “≈” do not mean the same thing.",ar:"الرمزان “=” و“≈” لا يعنيان الشيء نفسه."}},{id:"proportionality",stage:"proportionality",figureAfterSteps:!0,title:{eu:"Ehunekoak eta proportzionaltasuna",es:"Porcentajes y proporcionalidad",en:"Percentages and proportionality",ar:"النسب المئوية والتناسب"},goal:{eu:"Proportzionaltasun zuzeneko buruketak unitateko balioaz eta proportzioz ebaztea.",es:"Resolver problemas de proporcionalidad directa con el valor unitario y con proporciones.",en:"Solve direct proportion problems using the unit value and using proportions.",ar:"حلّ مسائل التناسب الطردي باستعمال قيمة الوحدة والتناسب."},problem:{eu:"3 koaderno 7,50 € badira, zenbat balio dute 5 koadernok?",es:"Si 3 cuadernos cuestan 7,50 €, ¿cuánto cuestan 5 cuadernos?",en:"If 3 notebooks cost €7.50, how much do 5 notebooks cost?",ar:"إذا كان ثمن 3 دفاتر 7.50€، فما ثمن 5 دفاتر؟"},stepsKind:"steps",steps:[{text:{eu:"Egiaztatu proportzionaltasun zuzena dela: koaderno bikoitzak, prezio bikoitza.",es:"Comprueba que es proporcionalidad directa: el doble de cuadernos cuesta el doble.",en:"Check that it is direct proportion: twice as many notebooks cost twice as much.",ar:"تحقّق أنه تناسب طردي: ضعف الدفاتر بضعف الثمن."}},{text:{eu:"Kalkulatu unitate baten balioa: 3 koaderno 7,50 € badira, bat 2,50 €.",es:"Calcula el valor de una unidad: si 3 cuadernos cuestan 7,50 €, uno cuesta 2,50 €.",en:"Work out the value of one unit: if 3 notebooks cost €7.50, one costs €2.50.",ar:"احسب قيمة الوحدة: إذا كان ثمن 3 دفاتر 7.50€ فثمن الواحد 2.50€."},math:d("$7{,}50\\div 3=2{,}50$")},{text:{eu:"Biderkatu eskatutako kantitateaz.",es:"Multiplica por la cantidad pedida.",en:"Multiply by the quantity asked for.",ar:"اضرب في الكمية المطلوبة."},math:d("$5\\cdot 2{,}50=12{,}50$")},{text:{eu:"Edo planteatu proportzio bat eta ebatzi.",es:"O plantea una proporción y resuélvela.",en:"Or set up a proportion and solve it.",ar:"أو اكتب تناسبًا وحلّه."},math:d("$\\frac{3}{7{,}50}=\\frac{5}{x}\\;\\rightarrow\\;x=\\frac{5\\cdot 7{,}50}{3}=12{,}50$")}],takeaway:{eu:"Testuinguruan, emaitzaren unitatea eta arrazoizkotasuna ere egiaztatu.",es:"En contexto, comprueba también la unidad y si el resultado es razonable.",en:"In context, also check the unit and whether the result is reasonable.",ar:"في المسائل السياقية تحقّق أيضًا من الوحدة ومن معقولية النتيجة."}}],I=v.map(t=>({...t,...g[t.id]})),T=[{id:601,prompt:{eu:"Zein adierazpenek du unitatea baino balio handiagoa?",es:"¿Qué expresión tiene un valor mayor que la unidad?",en:"Which expression has a value greater than one?",ar:"أي تعبير قيمته أكبر من الواحد؟"},options:[{eu:"3/7",es:"3/7",en:"3/7",ar:"3/7"},{eu:"7/3",es:"7/3",en:"7/3",ar:"7/3"},{eu:"5/5",es:"5/5",en:"5/5",ar:"5/5"}],correctIndex:1,explanation:{eu:"7/3 zatiki inpropioa da eta 2 1/3 balio du.",es:"7/3 es impropia y vale 2 1/3.",en:"7/3 is improper and equals 2 1/3.",ar:"7/3 كسر غير حقيقي وقيمته 2 و1/3."},topic:"representation"},{id:602,prompt:{eu:"Zein zatiki da 3/4-ren baliokidea?",es:"¿Qué fracción es equivalente a 3/4?",en:"Which fraction is equivalent to 3/4?",ar:"أي كسر يكافئ 3/4؟"},options:[{eu:"6/8",es:"6/8",en:"6/8",ar:"6/8"},{eu:"6/7",es:"6/7",en:"6/7",ar:"6/7"},{eu:"9/16",es:"9/16",en:"9/16",ar:"9/16"}],correctIndex:0,explanation:{eu:"Zenbakitzailea eta izendatzailea 2z biderkatu dira.",es:"Se han multiplicado numerador y denominador por 2.",en:"The numerator and denominator have been multiplied by 2.",ar:"ضُرب البسط والمقام في 2."},topic:"equivalence"},{id:603,prompt:{eu:"Zein da handiena?",es:"¿Cuál es la mayor?",en:"Which one is the largest?",ar:"أيها أكبر؟"},options:[{eu:"−2/3",es:"−2/3",en:"−2/3",ar:"−2/3"},{eu:"−3/4",es:"−3/4",en:"−3/4",ar:"−3/4"},{eu:"−5/6",es:"−5/6",en:"−5/6",ar:"−5/6"}],correctIndex:0,explanation:{eu:"Negatiboetan zerotik hurbilen dagoena da handiena.",es:"Entre negativos, el más cercano a cero es el mayor.",en:"Among negatives, the one closest to zero is the largest.",ar:"بين الأعداد السالبة يكون الأقرب إلى الصفر هو الأكبر."},topic:"ordering"},{id:604,prompt:{eu:"Zenbat da 1/3 + 1/6?",es:"¿Cuánto es 1/3 + 1/6?",en:"What is 1/3 + 1/6?",ar:"ما ناتج 1/3 + 1/6؟"},options:[{eu:"2/9",es:"2/9",en:"2/9",ar:"2/9"},{eu:"1/2",es:"1/2",en:"1/2",ar:"1/2"},{eu:"2/6",es:"2/6",en:"2/6",ar:"2/6"}],correctIndex:1,explanation:{eu:"1/3 = 2/6; beraz, 2/6 + 1/6 = 3/6 = 1/2.",es:"1/3 = 2/6; por tanto, 2/6 + 1/6 = 3/6 = 1/2.",en:"1/3 = 2/6; so 2/6 + 1/6 = 3/6 = 1/2.",ar:"1/3 = 2/6؛ إذن 2/6 + 1/6 = 3/6 = 1/2."},topic:"add-subtract"},{id:605,prompt:{eu:"Zenbat da 80ren %25?",es:"¿Cuánto es el 25 % de 80?",en:"What is 25% of 80?",ar:"كم يساوي 25٪ من 80؟"},options:[{eu:"20",es:"20",en:"20",ar:"20"},{eu:"25",es:"25",en:"25",ar:"25"},{eu:"32",es:"32",en:"32",ar:"32"}],correctIndex:0,explanation:{eu:"%25 = 1/4 eta 80ren laurdena 20 da.",es:"25 % = 1/4 y la cuarta parte de 80 es 20.",en:"25% = 1/4 and a quarter of 80 is 20.",ar:"25٪ = 1/4، وربع 80 يساوي 20."},topic:"percentages"},{id:606,prompt:{eu:"3 koaderno 7,50 € badira, zenbat balio dute 5ek?",es:"Si 3 cuadernos cuestan 7,50 €, ¿cuánto cuestan 5?",en:"If 3 notebooks cost €7.50, how much do 5 cost?",ar:"إذا كان ثمن 3 دفاتر 7.50€، فما ثمن 5؟"},options:[{eu:"10 €",es:"10 €",en:"€10",ar:"10€"},{eu:"12,50 €",es:"12,50 €",en:"€12.50",ar:"12.50€"},{eu:"15 €",es:"15 €",en:"€15",ar:"15€"}],correctIndex:1,explanation:{eu:"Koaderno bakoitza 2,50 € da; bostek 12,50 € balio dute.",es:"Cada cuaderno cuesta 2,50 €; cinco cuestan 12,50 €.",en:"Each notebook costs €2.50; five cost €12.50.",ar:"ثمن الدفتر 2.50€؛ وثمن خمسة دفاتر 12.50€."},topic:"proportionality"}],P=[{id:"meaning",tone:"blue",icon:"◐",color:"#38bdf8",title:{eu:"Zer adierazten du zatiki batek?",es:"¿Qué representa una fracción?",en:"What does a fraction represent?",ar:"ماذا يمثّل الكسر؟"},goal:{eu:"Zatikia zati gisa, zatidura gisa eta zenbaki gisa interpretatzea.",es:"Interpretar una fracción como parte, cociente y número.",en:"Interpret a fraction as a part, a quotient and a number.",ar:"تفسير الكسر بوصفه جزءًا وقسمةً وعددًا."},explanation:{eu:"Izendatzaileak unitatea zenbat zati berdinetan banatzen den adierazten du; zenbakitzaileak zenbat zati hartzen diren. Balioa zenbaki-zuzenean puntu bakar bat da.",es:"El denominador indica en cuántas partes iguales se divide la unidad; el numerador, cuántas se toman. Su valor es un punto concreto de la recta numérica.",en:"The denominator shows how many equal parts the whole is divided into; the numerator, how many are taken. Its value is a specific point on the number line.",ar:"يبيّن المقام عدد الأجزاء المتساوية للوحدة، ويبيّن البسط عدد الأجزاء المأخوذة. وقيمة الكسر نقطة محددة على خط الأعداد."},example:"$\\frac{7}{3}=2\\frac{1}{3}$",takeaway:{eu:"Zatiki inpropio batek unitate bat baino gehiago ere adieraz dezake.",es:"Una fracción impropia también puede representar más de una unidad.",en:"An improper fraction can also represent more than one whole.",ar:"يمكن للكسر غير الحقيقي أن يمثّل أكثر من وحدة."}},{id:"equivalence",tone:"violet",icon:"≡",color:"#a78bfa",title:{eu:"Baliokidetasuna eta sinplifikazioa",es:"Equivalencia y simplificación",en:"Equivalence and simplification",ar:"التكافؤ والتبسيط"},goal:{eu:"Itxura desberdina duten baina balio bera duten zatikiak identifikatzea.",es:"Reconocer fracciones con distinta apariencia y el mismo valor.",en:"Recognise fractions that look different but have the same value.",ar:"تمييز الكسور المختلفة في الشكل والمتساوية في القيمة."},explanation:{eu:"Zenbakitzailea eta izendatzailea zero ez den zenbaki berarekin biderkatzeak edo zatitzeak ez du balioa aldatzen.",es:"Multiplicar o dividir numerador y denominador por el mismo número distinto de cero no cambia el valor.",en:"Multiplying or dividing the numerator and denominator by the same non-zero number does not change the value.",ar:"لا تتغيّر القيمة عند ضرب البسط والمقام أو قسمتهما على العدد نفسه غير الصفري."},example:"$\\frac{3}{4}=\\frac{6}{8}=\\frac{45}{60}$",takeaway:{eu:"Sinplifikatzea baliokidea den zatiki laburrena aurkitzea da.",es:"Simplificar es encontrar la fracción equivalente más reducida.",en:"Simplifying means finding the equivalent fraction in its simplest form.",ar:"التبسيط هو إيجاد الكسر المكافئ في أبسط صورة."}},{id:"ordering",tone:"mustard",icon:"↔",color:"#f59e0b",title:{eu:"Konparazioa eta ordena",es:"Comparación y orden",en:"Comparison and order",ar:"المقارنة والترتيب"},goal:{eu:"Zatiki positiboak eta negatiboak estrategia egokiaz ordenatzea.",es:"Ordenar fracciones positivas y negativas eligiendo una estrategia adecuada.",en:"Order positive and negative fractions by choosing a suitable strategy.",ar:"ترتيب الكسور الموجبة والسالبة باختيار استراتيجية مناسبة."},explanation:{eu:"Izendatzaile komuna, biderketa gurutzatua edo zenbaki-zuzena erabil daitezke. Zeinuari begiratu lehenik: zenbaki negatiboa positiboa baino txikiagoa da.",es:"Puedes usar denominador común, productos cruzados o la recta numérica. Observa primero el signo: todo número negativo es menor que uno positivo.",en:"You can use a common denominator, cross-multiplication or the number line. Look at the sign first: every negative number is less than a positive one.",ar:"يمكن استعمال مقام مشترك أو الضرب التبادلي أو خط الأعداد. ابدأ بالإشارة: كل عدد سالب أصغر من أي عدد موجب."},example:"$-\\frac{2}{3}<\\frac{1}{4}<\\frac{5}{6}$",takeaway:{eu:"Metodoa baino garrantzitsuagoa da konparazioa arrazoitzea.",es:"Más importante que el método es poder justificar la comparación.",en:"More important than the method is being able to justify the comparison.",ar:"الأهم من الطريقة هو القدرة على تبرير المقارنة."}},{id:"operations",tone:"coral",icon:"±",color:"#fb7185",title:{eu:"Eragiketak eta zeinuak",es:"Operaciones y signos",en:"Operations and signs",ar:"العمليات والإشارات"},goal:{eu:"Batuketak, kenketak, biderketak eta zatiketak zehaztasunez egitea.",es:"Resolver sumas, restas, multiplicaciones y divisiones con exactitud.",en:"Work out additions, subtractions, multiplications and divisions accurately.",ar:"حل الجمع والطرح والضرب والقسمة بدقة."},explanation:{eu:"Batuketan eta kenketan izendatzaile komuna behar da. Biderketan zuzenean biderkatzen da; zatiketan, bigarren zatikiaren alderantzizkoarekin biderkatzen da.",es:"Para sumar o restar se necesita denominador común. Para multiplicar se opera en línea; para dividir se multiplica por la inversa de la segunda fracción.",en:"To add or subtract, you need a common denominator. To multiply, work straight across; to divide, multiply by the reciprocal of the second fraction.",ar:"في الجمع والطرح نحتاج إلى مقام مشترك. وفي الضرب نضرب مباشرة، وفي القسمة نضرب في مقلوب الكسر الثاني."},example:"$\\frac{1}{3}-\\frac{5}{6}=-\\frac{1}{2}$",takeaway:{eu:"Kalkulu bakoitza emaitza sinplifikatuz eta zeinua egiaztatuz amaitu.",es:"Termina cada cálculo simplificando el resultado y comprobando su signo.",en:"Finish each calculation by simplifying the result and checking its sign.",ar:"اختم كل عملية بتبسيط النتيجة والتحقق من إشارتها."}},{id:"proportionality",tone:"green",icon:"%",color:"#34d399",title:{eu:"Ehunekoak eta proportzionaltasuna",es:"Porcentajes y proporcionalidad",en:"Percentages and proportionality",ar:"النسب المئوية والتناسب"},goal:{eu:"Zatikiak egoera errealetako ehunekoekin eta proportzioekin lotzea.",es:"Relacionar fracciones con porcentajes y proporciones de situaciones reales.",en:"Link fractions with percentages and proportions in real situations.",ar:"ربط الكسور بالنسب المئوية والتناسب في مواقف واقعية."},explanation:{eu:"Ehunekoa 100 izendatzailea duen zatikia da. Proportzio batean bi arrazoik balio bera dute; horregatik, unitateko balioa edo baliokidetasuna erabil daiteke.",es:"Un porcentaje es una fracción de denominador 100. En una proporción dos razones tienen el mismo valor, por lo que puedes usar el valor unitario o la equivalencia.",en:"A percentage is a fraction with denominator 100. In a proportion, two ratios have the same value, so you can use the unit rate or equivalent ratios.",ar:"النسبة المئوية كسر مقامه 100. وفي التناسب تكون نسبتان متساويتين، لذلك يمكن استعمال قيمة الوحدة أو التكافؤ."},example:"$35\\%=\\frac{35}{100}=\\frac{7}{20}$",takeaway:{eu:"Testuinguruan, emaitzaren unitatea eta arrazoizkotasuna ere egiaztatu.",es:"En contexto, comprueba también la unidad y si el resultado es razonable.",en:"In context, also check the unit and whether the result is reasonable.",ar:"في المسائل السياقية تحقّق أيضًا من الوحدة ومن معقولية النتيجة."}}],A=[{id:1,stage:"meaning",prompt:{eu:"Idatzi zenbaki misto gisa.",es:"Escribe como número mixto.",en:"Write it as a mixed number.",ar:"اكتب في صورة عدد كسري."},expression:"$\\frac{7}{3}$",expected:a(7,3),answerForm:"mixed",hint:{eu:"Zatitu 7 zati 3.",es:"Divide 7 entre 3.",en:"Divide 7 by 3.",ar:"اقسم 7 على 3."},explanation:{eu:"Bi unitate oso eta heren bat geratzen dira.",es:"Hay dos unidades completas y queda un tercio.",en:"There are two whole units and one third left over.",ar:"توجد وحدتان كاملتان ويتبقى ثلث."}},{id:2,stage:"equivalence",prompt:{eu:"Sinplifikatu.",es:"Simplifica.",en:"Simplify.",ar:"بسّط."},expression:"$\\frac{45}{60}$",expected:a(3,4),answerForm:"simplified",hint:{eu:"Zatitu biak 15ez.",es:"Divide ambos términos entre 15.",en:"Divide both terms by 15.",ar:"اقسم البسط والمقام على 15."},explanation:{eu:"$45\\div15=3$ eta $60\\div15=4$.",es:"$45\\div15=3$ y $60\\div15=4$.",en:"$45\\div15=3$ and $60\\div15=4$.",ar:"$45\\div15=3$ و$60\\div15=4$."}},{id:3,stage:"ordering",prompt:{eu:"Zein da txikiena? Idatzi haren balioa.",es:"¿Cuál es la menor? Escribe su valor.",en:"Which is the smallest? Write its value.",ar:"ما الكسر الأصغر؟ اكتب قيمته."},expression:"$-\\frac{2}{3},\\;\\frac{1}{4},\\;\\frac{5}{6}$",expected:a(-2,3),hint:{eu:"Begiratu zeinuari lehenik.",es:"Observa primero el signo.",en:"Look at the sign first.",ar:"انظر أولًا إلى الإشارة."},explanation:{eu:"Zerrendako balio negatibo bakarra da.",es:"Es el único valor negativo de la lista.",en:"It is the only negative value in the list.",ar:"إنه العدد السالب الوحيد في القائمة."}},{id:4,stage:"operations",prompt:{eu:"Kalkulatu eta sinplifikatu.",es:"Calcula y simplifica.",en:"Calculate and simplify.",ar:"احسب وبسّط."},expression:"$\\frac{1}{3}-\\frac{5}{6}$",expected:a(-1,2),answerForm:"simplified",hint:{eu:"Idatzi herenak seiren gisa.",es:"Escribe los tercios como sextos.",en:"Write the thirds as sixths.",ar:"حوّل الأثلاث إلى أسداس."},explanation:{eu:"$2/6-5/6=-3/6=-1/2$.",es:"$2/6-5/6=-3/6=-1/2$.",en:"$2/6-5/6=-3/6=-1/2$.",ar:"$2/6-5/6=-3/6=-1/2$."}},{id:5,stage:"operations",prompt:{eu:"Kalkulatu eta sinplifikatu.",es:"Calcula y simplifica.",en:"Calculate and simplify.",ar:"احسب وبسّط."},expression:"$-\\frac{2}{5}\\cdot\\frac{15}{8}$",expected:a(-3,4),answerForm:"simplified",hint:{eu:"Sinplifikatu gurutzatuta biderkatu aurretik.",es:"Simplifica en cruz antes de multiplicar.",en:"Cross-cancel before multiplying.",ar:"اختصر تبادليًا قبل الضرب."},explanation:{eu:"Zeinuak negatiboa ematen du eta balioa $-30/40=-3/4$ da.",es:"El signo es negativo y el valor es $-30/40=-3/4$.",en:"The sign is negative and the value is $-30/40=-3/4$.",ar:"الإشارة سالبة والقيمة $-30/40=-3/4$."}},{id:6,stage:"operations",prompt:{eu:"Kalkulatu eta sinplifikatu.",es:"Calcula y simplifica.",en:"Calculate and simplify.",ar:"احسب وبسّط."},expression:"$\\frac{5}{6}\\div\\left(-\\frac{10}{9}\\right)$",expected:a(-3,4),answerForm:"simplified",hint:{eu:"Biderkatu bigarren zatikiaren alderantzizkoarekin.",es:"Multiplica por la inversa de la segunda fracción.",en:"Multiply by the reciprocal of the second fraction.",ar:"اضرب في مقلوب الكسر الثاني."},explanation:{eu:"$5/6\\cdot(-9/10)=-45/60=-3/4$.",es:"$5/6\\cdot(-9/10)=-45/60=-3/4$.",en:"$5/6\\cdot(-9/10)=-45/60=-3/4$.",ar:"$5/6\\cdot(-9/10)=-45/60=-3/4$."}},{id:7,stage:"proportionality",prompt:{eu:"Kalkulatu 240ren %35.",es:"Calcula el 35 % de 240.",en:"Calculate 35% of 240.",ar:"احسب 35٪ من 240."},expected:a(84),hint:{eu:"Biderkatu 240 × 35/100.",es:"Multiplica 240 × 35/100.",en:"Multiply 240 × 35/100.",ar:"اضرب 240 × 35/100."},explanation:{eu:"$240\\cdot35/100=84$.",es:"$240\\cdot35/100=84$.",en:"$240\\cdot35/100=84$.",ar:"$240\\cdot35/100=84$."}},{id:8,stage:"proportionality",prompt:{eu:"3 koaderno 7,50 € badira, zenbat balio dute 5ek?",es:"Si 3 cuadernos cuestan 7,50 €, ¿cuánto cuestan 5?",en:"If 3 notebooks cost €7.50, how much do 5 cost?",ar:"إذا كان ثمن 3 دفاتر 7.50€، فما ثمن 5؟"},expected:a(25,2),hint:{eu:"Aurkitu koaderno baten prezioa.",es:"Calcula primero el precio de un cuaderno.",en:"First, work out the price of one notebook.",ar:"احسب أولًا ثمن دفتر واحد."},explanation:{eu:"$7,50\\div3=2,50$ eta $2,50\\cdot5=12,50$.",es:"$7,50\\div3=2,50$ y $2,50\\cdot5=12,50$.",en:"$7,50\\div3=2,50$ and $2,50\\cdot5=12,50$.",ar:"$7.50\\div3=2.50$ ثم $2.50\\cdot5=12.50$."}},{id:9,stage:"equivalence",prompt:{eu:"$1/3$ eta $0,33$ arteko diferentzia zehatza kalkulatu.",es:"Calcula la diferencia exacta entre $1/3$ y $0,33$.",en:"Work out the exact difference between $1/3$ and $0,33$.",ar:"احسب الفرق الدقيق بين $1/3$ و$0.33$."},expected:a(1,300),hint:{eu:"$0,33=33/100$; erabili 300 izendatzailea.",es:"$0,33=33/100$; usa denominador 300.",en:"$0,33=33/100$; use denominator 300.",ar:"$0.33=33/100$؛ استعمل المقام 300."},explanation:{eu:"$1/3-33/100=100/300-99/300=1/300$. Horregatik $0,33$ hurbilketa da.",es:"$1/3-33/100=100/300-99/300=1/300$. Por eso $0,33$ es una aproximación.",en:"$1/3-33/100=100/300-99/300=1/300$. That is why $0,33$ is an approximation.",ar:"$1/3-33/100=100/300-99/300=1/300$، لذلك $0.33$ قيمة تقريبية."}},{id:10,stage:"proportionality",prompt:{eu:"Kalkulurik egin gabe, hurbildu $198$ren $49/100$ hamarreko hurbilenera.",es:"Sin hacer el cálculo exacto, estima $49/100$ de $198$ a la decena más cercana.",en:"Without doing the exact calculation, estimate $49/100$ of $198$ to the nearest ten.",ar:"من دون حساب دقيق، قدّر $49/100$ من $198$ إلى أقرب عشرة."},expected:a(100),hint:{eu:"$49/100\\approx1/2$ eta $198\\approx200$.",es:"$49/100\\approx1/2$ y $198\\approx200$.",en:"$49/100\\approx1/2$ and $198\\approx200$.",ar:"$49/100\\approx1/2$ و$198\\approx200$."},explanation:{eu:"Erdia 200rena 100 da; emaitza zehatza 97,02 da, beraz estimazioa arrazoizkoa da.",es:"La mitad de 200 es 100; el valor exacto es 97,02, así que la estimación es razonable.",en:"Half of 200 is 100; the exact value is 97.02, so the estimate is reasonable.",ar:"نصف 200 هو 100؛ والقيمة الدقيقة 97.02، لذا فالتقدير معقول."}}],y=[{id:104,stage:"equivalence",context:"starter",points:10,prompt:{eu:"60 minutuko saio batean 45 minutu erabili dira. Zein zati da?",es:"En una sesión de 60 minutos se usan 45. ¿Qué fracción representa?",en:"In a 60-minute session, 45 minutes are used. What fraction does that represent?",ar:"استُعملت 45 دقيقة من حصة مدتها 60 دقيقة. ما الكسر؟"},expected:a(3,4),hint:{eu:"Idatzi 45/60 eta sinplifikatu.",es:"Escribe 45/60 y simplifica.",en:"Write 45/60 and simplify.",ar:"اكتب 45/60 ثم بسّط."},explanation:{eu:"$45/60=3/4$.",es:"$45/60=3/4$.",en:"$45/60=3/4$.",ar:"$45/60=3/4$."}},{id:106,stage:"operations",context:"advanced",points:20,prompt:{eu:"Errezeta baterako 2/3 L behar dira. 2,5 errezeta egiteko, zenbat litro?",es:"Una receta necesita 2/3 L. ¿Cuántos litros hacen falta para 2,5 recetas?",en:"A recipe needs 2/3 L. How many litres are needed for 2.5 recipes?",ar:"تحتاج الوصفة إلى 2/3 لتر. كم لترًا نحتاج لإعداد 2.5 وصفة؟"},expected:a(5,3),hint:{eu:"Biderkatu $2/3\\cdot5/2$.",es:"Multiplica $2/3\\cdot5/2$.",en:"Multiply $2/3\\cdot5/2$.",ar:"اضرب $2/3\\cdot5/2$."},explanation:{eu:"$2/3\\cdot5/2=5/3$ L.",es:"$2/3\\cdot5/2=5/3$ L.",en:"$2/3\\cdot5/2=5/3$ L.",ar:"$2/3\\cdot5/2=5/3$ لتر."}},{id:108,stage:"proportionality",context:"advanced",points:20,prompt:{eu:"Ibilbide baten 3/5 21 minutuan egiten dira. Zenbat minutu behar dira osorik?",es:"Se recorren 3/5 de una ruta en 21 minutos. ¿Cuánto se tarda en completarla?",en:"3/5 of a route is covered in 21 minutes. How long does it take to complete it?",ar:"قُطع 3/5 من مسار في 21 دقيقة. كم يستغرق المسار كاملًا؟"},expected:a(35),hint:{eu:"Aurkitu lehenengo bosten baten denbora.",es:"Calcula primero el tiempo de un quinto.",en:"First, work out the time for one fifth.",ar:"احسب أولًا زمن الخُمس الواحد."},explanation:{eu:"$21\\div3=7$ eta $7\\cdot5=35$ min.",es:"$21\\div3=7$ y $7\\cdot5=35$ min.",en:"$21\\div3=7$ and $7\\cdot5=35$ min.",ar:"$21\\div3=7$ ثم $7\\cdot5=35$ دقيقة."}},{id:112,stage:"proportionality",context:"master",points:40,prompt:{eu:"Ur-biltegi batetik 1/4 erabili da; ondoren, geratzen denaren 1/3; eta gero, geratzen denaren 2/5. Amaieran 1800 L daude. Zenbat zegoen hasieran?",es:"De un depósito se usa 1/4; después, 1/3 de lo que queda; y luego, 2/5 de lo restante. Al final quedan 1800 L. ¿Cuánto había al principio?",en:"1/4 of a tank is used; then 1/3 of what is left; and then 2/5 of what remains. At the end, 1,800 L are left. How much was there at the start?",ar:"استُعمل ربع خزان، ثم ثلث الباقي، ثم خُمسا ما تبقّى. بقي في النهاية 1800 لتر. كم كانت الكمية في البداية؟"},expected:a(6e3),hint:{eu:"Geratzen den zatia $(3/4)(2/3)(3/5)$ da.",es:"La fracción restante es $(3/4)(2/3)(3/5)$.",en:"The fraction remaining is $(3/4)(2/3)(3/5)$.",ar:"الكسر المتبقي هو $(3/4)(2/3)(3/5)$."},explanation:{eu:"Geratzen da $3/10$; beraz, $1800\\div3/10=6000$ L.",es:"Queda $3/10$; por tanto, $1800\\div3/10=6000$ L.",en:"$3/10$ remains; so, $1800\\div3/10=6000$ L.",ar:"يتبقى $3/10$؛ إذن $1800\\div3/10=6000$ لتر."}}],x=[{id:101,stage:"proportionality",context:"starter",points:10,prompt:{eu:"Baserriak 24 sagar ditu eta uztaren 3/4 bildu dira. Zenbat sagar bildu dira?",es:"Una granja tiene 24 manzanas y se recogen 3/4 de la cosecha. ¿Cuántas manzanas son?",en:"A farm has 24 apples and 3/4 of the harvest is picked. How many apples is that?",ar:"في المزرعة 24 تفاحة، وجُمع 3/4 المحصول. كم تفاحة جُمعت؟"},expected:a(18),hint:{eu:"Kalkulatu $24\\cdot3/4$.",es:"Calcula $24\\cdot3/4$.",en:"Calculate $24\\cdot3/4$.",ar:"احسب $24\\cdot3/4$."},explanation:{eu:"$24\\div4\\cdot3=18$ sagar.",es:"$24\\div4\\cdot3=18$ manzanas.",en:"$24\\div4\\cdot3=18$ apples.",ar:"$24\\div4\\cdot3=18$ تفاحة."}},{id:102,stage:"operations",context:"starter",points:10,prompt:{eu:"Pizza erdia duzu eta lagun batek beste 1/4 ematen dizu. Zenbat pizza duzu?",es:"Tienes media pizza y una amiga te da otro cuarto. ¿Cuánta pizza tienes?",en:"You have half a pizza and a friend gives you another quarter. How much pizza do you have?",ar:"لديك نصف بيتزا وأعطاك صديق ربعًا آخر. كم لديك؟"},expected:a(3,4),hint:{eu:"Bihurtu $1/2$ laurdenetara.",es:"Convierte $1/2$ en cuartos.",en:"Convert $1/2$ into quarters.",ar:"حوّل $1/2$ إلى أرباع."},explanation:{eu:"$1/2+1/4=2/4+1/4=3/4$.",es:"$1/2+1/4=2/4+1/4=3/4$.",en:"$1/2+1/4=2/4+1/4=3/4$.",ar:"$1/2+1/4=2/4+1/4=3/4$."}},{id:103,stage:"meaning",context:"starter",points:10,prompt:{eu:"Tarta bat 8 zati berdinetan banatu da eta 3 jan dira. Zer zatiki jan da?",es:"Una tarta se divide en 8 partes iguales y se comen 3. ¿Qué fracción se ha comido?",en:"A cake is divided into 8 equal pieces and 3 are eaten. What fraction has been eaten?",ar:"قُسمت كعكة إلى 8 أجزاء متساوية وأُكلت 3. ما الكسر المأكول؟"},expected:a(3,8),hint:{eu:"Jan diren zatiak / zatiak guztira.",es:"Partes comidas / partes totales.",en:"Parts eaten / total parts.",ar:"الأجزاء المأكولة / مجموع الأجزاء."},explanation:{eu:"3 zati 8tik: $3/8$.",es:"3 partes de 8: $3/8$.",en:"3 parts out of 8: $3/8$.",ar:"3 أجزاء من 8: $3/8$."}},{id:105,stage:"operations",context:"advanced",points:20,prompt:{eu:"Lur baten 1/3 sagarrondoa da eta 1/4 baratzea. Gainerakoaren zer zatiki da larrea?",es:"De un terreno, 1/3 es manzanal y 1/4 huerta. ¿Qué fracción queda para pasto?",en:"Of a plot of land, 1/3 is an apple orchard and 1/4 is a vegetable garden. What fraction is left for pasture?",ar:"خُصص 1/3 أرض لأشجار التفاح و1/4 للحديقة. ما الكسر المتبقي للمرعى؟"},expected:a(5,12),hint:{eu:"Kendu $1/3+1/4$ unitatetik.",es:"Resta $1/3+1/4$ de la unidad.",en:"Subtract $1/3+1/4$ from the whole.",ar:"اطرح $1/3+1/4$ من الواحد."},explanation:{eu:"$1-4/12-3/12=5/12$.",es:"$1-4/12-3/12=5/12$.",en:"$1-4/12-3/12=5/12$.",ar:"$1-4/12-3/12=5/12$."}},{id:107,stage:"proportionality",context:"advanced",points:20,prompt:{eu:"Ikasleen %60k gainditu du. Zein da zatiki laburtezina?",es:"El 60 % del alumnado ha aprobado. ¿Cuál es la fracción irreducible?",en:"60% of the students have passed. What is the fraction in its simplest form?",ar:"نجح 60٪ من الطلاب. ما الكسر في أبسط صورة؟"},expected:a(3,5),answerForm:"simplified",hint:{eu:"$60/100$ sinplifikatu.",es:"Simplifica $60/100$.",en:"Simplify $60/100$.",ar:"بسّط $60/100$."},explanation:{eu:"$60/100=3/5$.",es:"$60/100=3/5$.",en:"$60/100=3/5$.",ar:"$60/100=3/5$."}},{id:109,stage:"proportionality",context:"master",points:30,prompt:{eu:"Pilota batek aurreko altueraren 2/3 lortzen du bote bakoitzean. Bigarren botea 8 m bada, zein zen hasierako altuera?",es:"Una pelota alcanza 2/3 de la altura anterior en cada bote. Si el segundo bote llega a 8 m, ¿cuál era la altura inicial?",en:"A ball reaches 2/3 of its previous height on each bounce. If the second bounce reaches 8 m, what was the starting height?",ar:"تصل كرة في كل ارتداد إلى 2/3 الارتفاع السابق. إذا بلغ الارتداد الثاني 8 م، فما الارتفاع الابتدائي؟"},expected:a(18),hint:{eu:"Egin alderantziz bi aldiz: $8\\div2/3\\div2/3$.",es:"Trabaja hacia atrás dos veces: $8\\div2/3\\div2/3$.",en:"Work backwards twice: $8\\div2/3\\div2/3$.",ar:"اعمل عكسيًا مرتين: $8\\div2/3\\div2/3$."},explanation:{eu:"$18\\cdot2/3=12$ eta $12\\cdot2/3=8$.",es:"$18\\cdot2/3=12$ y $12\\cdot2/3=8$.",en:"$18\\cdot2/3=12$ and $12\\cdot2/3=8$.",ar:"$18\\cdot2/3=12$ ثم $12\\cdot2/3=8$."}},{id:110,stage:"proportionality",context:"master",points:30,prompt:{eu:"Grifo batek 2 ordutan eta besteak 6 ordutan betetzen dute depositua. Zenbat minutu behar dituzte batera?",es:"Un grifo llena un depósito en 2 horas y otro en 6. ¿Cuántos minutos tardan juntos?",en:"One tap fills a tank in 2 hours and another in 6 hours. How many minutes do they take together?",ar:"يملأ صنبور خزانًا في ساعتين وآخر في 6 ساعات. كم دقيقة يحتاجان معًا؟"},expected:a(90),hint:{eu:"Orduko erritmoak batu: $1/2+1/6$.",es:"Suma los ritmos por hora: $1/2+1/6$.",en:"Add the rates per hour: $1/2+1/6$.",ar:"اجمع معدلي الملء في الساعة: $1/2+1/6$."},explanation:{eu:"Batera $2/3$ depositu/ordu; denbora $3/2$ ordu = 90 min.",es:"Juntos llenan $2/3$ de depósito por hora; tardan $3/2$ h = 90 min.",en:"Together they fill $2/3$ of a tank per hour; they take $3/2$ h = 90 min.",ar:"يملآن $2/3$ الخزان في الساعة؛ الزمن $3/2$ ساعة = 90 دقيقة."}},{id:111,stage:"proportionality",context:"master",points:30,prompt:{eu:"Soldataren 1/4 alokairuan eta geratzen denaren 1/3 janarian gastatu dira. 600 € geratzen badira, zein zen soldata?",es:"Se gasta 1/4 del salario en alquiler y 1/3 de lo restante en comida. Si quedan 600 €, ¿cuál era el salario?",en:"1/4 of the salary is spent on rent and 1/3 of what remains on food. If €600 is left over, what was the salary?",ar:"صُرف 1/4 الراتب على الإيجار و1/3 الباقي على الطعام. إذا بقي 600€، فما الراتب؟"},expected:a(1200),hint:{eu:"Alokairuaren ondoren $3/4$ geratzen da; horren $2/3$ geratuko da janariaren ondoren.",es:"Tras el alquiler queda $3/4$; después de la comida queda $2/3$ de esa cantidad.",en:"After rent, $3/4$ is left; after food, $2/3$ of that amount is left.",ar:"بعد الإيجار يبقى $3/4$، وبعد الطعام يبقى $2/3$ من ذلك."},explanation:{eu:"Geratzen da $(3/4)(2/3)=1/2$; $600\\div1/2=1200$ €.",es:"Queda $(3/4)(2/3)=1/2$; $600\\div1/2=1200$ €.",en:"$(3/4)(2/3)=1/2$ is left; $600\\div1/2=1200$ €.",ar:"يتبقى $(3/4)(2/3)=1/2$؛ $600\\div1/2=1200$ €."}}],B=[...x,...y].sort((t,n)=>t.id-n.id);function w(t){return n=>k(t,n)}const q=["<","=",">"],Z={"<":{eu:"Txikiagoa",es:"Menor",en:"Smaller",ar:"أصغر"},"=":{eu:"Berdina",es:"Igual",en:"Equal",ar:"يساوي"},">":{eu:"Handiagoa",es:"Mayor",en:"Bigger",ar:"أكبر"}};function M({language:t,question:n,labels:u=Z,actual:l,choice:o,tip:f,wait:b,onChoose:z,children:h}){const s=w(t),m=o===l;return r.jsxs(r.Fragment,{children:[r.jsxs("div",{className:"prediction",children:[r.jsx("p",{className:"prediction-question",children:r.jsx(p,{text:s(n)})}),r.jsx("div",{className:"prediction-options",role:"group","aria-label":s({eu:"Zure iragarpena",es:"Tu predicción",en:"Your prediction",ar:"توقّعك"}),children:q.map(c=>r.jsx("button",{type:"button","aria-pressed":o===c,className:o===null?"":c===l?"right":c===o?"wrong":"",disabled:o!==null,onClick:()=>z(c),children:s(u[c])},c))}),o!==null&&r.jsxs("p",{className:`prediction-feedback ${m?"right":"wrong"}`,"aria-live":"polite",children:[r.jsx("strong",{children:s(m?{eu:"Ondo pentsatuta!",es:"¡Bien pensado!",en:"Good thinking!",ar:"أحسنت التفكير!"}:{eu:"Ez da horrela.",es:"No es así.",en:"That’s not right.",ar:"ليس كذلك."})})," ",r.jsx(p,{text:s(f)})]})]}),o===null?r.jsx("p",{className:"prediction-wait",children:s(b??{eu:"Iragarri lehenik; gero idatzi emaitza.",es:"Primero predice; después escribe el resultado.",en:"First predict; then write the result.",ar:"توقّع أولًا، ثم اكتب النتيجة."})}):h]})}export{M as P,B as c,T as d,A as g,P as l,I as t,w as u};
